        flex-direction: column;
        align-items: start;
}

.quick-access-card{
    display: inline-flex;
    align-items: center;
    width: 193px;
    flex-direction: row;
    padding: 18px 2px 18px 10px;
    gap: 8px;

    border-radius: 8px;
    border: 1px solid rgba(91, 91, 95, 0.20);
    background: var(--Current-In-prod-color-default, #FFF);
    box-shadow: 0 4px 4px 0 rgba(0, 0, 0, 0.03);
    transition: all 0.3s ease;
    cursor: pointer;
}

.quick-access-card:hover{
    border: 1px solid var(--Current-In-prod-color-trust, #0435AC);
    text-decoration: none;
}

.quick-access-card:active{
    background: var(--Current-In-prod-color-alternative, #162A59);
    border: 1px solid transparent;
}

.quick-access-card
    img{
        display: inline-block;
        width: 20px;
        height: 20px;
        flex-shrink: 0;
}

.quick-access-card
    .title-card{
        display: -webkit-box;
        color: var(--Current-In-prod-color-alternative, #162A59);
        font-family: 'oxygen-regular';
        font-size: 14px!important;
        font-style: normal;
        font-weight: 400;

        -webkit-line-clamp: 1;
        -webkit-box-orient: vertical;
        overflow: hidden;
        text-overflow: ellipsis;
}

.quick-access-card:active
    .title-card{
        color: var(--Current-In-prod-color-default, #FFF);
}

.quick-access-card
    .title-container{
        display: inline-flex;
        justify-content: space-between;
        width: 100%;
}

