(function () {
    function initCarousel() {
        var container = document.querySelector(
            '.header-banner .content-container .banner-zone-2 .container-fluid'
        );

        if (!container || container.dataset.carouselReady) return;
        container.dataset.carouselReady = 'true';

        var slides = Array.from(container.querySelectorAll(':scope > .row'));
        if (slides.length === 0) return;

        if (slides.length < 2) {
            slides[0].classList.add('active');
            container.classList.add('single-slide');
            return;
        }

        var currentIndex = 0;
        var interval = null;
        var isPaused = false;
        var INTERVAL_MS = 4000;

        function createArrow(direction) {
            var btn = document.createElement('button');
            btn.className = 'banner-zone-2-arrow ' + direction;
            btn.setAttribute('aria-label', direction === 'prev' ? 'Anterior' : 'Próximo');

            btn.addEventListener('click', function () {
                goTo(currentIndex + (direction === 'prev' ? -1 : 1));
                resetInterval();
            });

            container.appendChild(btn);
        }

        function createPause() {
            var btn = document.createElement('button');
            btn.className = 'banner-zone-2-pause';
            btn.setAttribute('aria-label', 'Pausar carrossel');
            btn.setAttribute('aria-pressed', 'false');

            updatePauseIcon(btn, false);

            btn.addEventListener('click', function () {
                isPaused = !isPaused;
                btn.setAttribute('aria-pressed', isPaused ? 'true' : 'false');
                btn.setAttribute('aria-label', isPaused ? 'Retomar carrossel' : 'Pausar carrossel');
                updatePauseIcon(btn, isPaused);

                if (isPaused) {
                    clearInterval(interval);
                } else {
                    resetInterval();
                }
            });

            container.appendChild(btn);
        }

        function updatePauseIcon(btn, paused) {
            btn.innerHTML = paused
                ? '<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><polygon points="5,3 19,12 5,21"/></svg>'
                : '<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="3" width="4" height="18"/><rect x="15" y="3" width="4" height="18"/></svg>';
        }

        createArrow('prev');
        createArrow('next');
        createPause();

        function goTo(index) {
            slides[currentIndex].classList.remove('active');
            currentIndex = (index + slides.length) % slides.length;
            slides[currentIndex].classList.add('active');
        }

        function next() {
            goTo(currentIndex + 1);
        }

        function resetInterval() {
            clearInterval(interval);
            if (!isPaused) {
                interval = setInterval(next, INTERVAL_MS);
            }
        }

        goTo(0);
        resetInterval();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCarousel);
    } else {
        initCarousel();
    }
}());;

