(function () {
  var btn = fragmentElement.querySelector('.hpv-search-btn');
  if (!btn) return;
  var isOpen = false;

  function updateAria() {
    btn.setAttribute('aria-label', isOpen ? 'Fechar busca' : 'Abrir busca');
    btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  }

  btn.addEventListener('click', function () {
    if (isOpen) {
      document.dispatchEvent(new CustomEvent('hapvida:closeSearch'));
    } else {
      document.dispatchEvent(new CustomEvent('hapvida:openSearch'));
    }
  });

  document.addEventListener('hapvida:openSearch', function () {
    isOpen = true;
    updateAria();

    var live = document.getElementById('hpv-search-live');
    if (live) {
      live.textContent = '';
      requestAnimationFrame(function () {
        live.textContent = 'Campo de busca aberto. Digite o termo e pressione Enter.';
      });
    }
  });

  document.addEventListener('hapvida:searchClosed', function () {
    isOpen = false;
    updateAria();
    btn.focus();
    var live = document.getElementById('hpv-search-live');
    if (live) {
      live.textContent = '';
    }
  });

  updateAria(); // estado inicial
})();;

