(function () {

    // ARIA-LABEL COUNTER
    function updateAriaLabels(header) {
        header.querySelectorAll('.link-group.link-parent').forEach(function (group, index) {
            group.setAttribute('aria-label', 'Menu column ' + (index + 1));
        });
    }

    function getFocusableChildren(el) {
        return Array.from(el.querySelectorAll(
            'a[href], button, [role="button"], [role="menuitem"], [tabindex]'
        ));
    }

    function setFocusable(el, focusable) {
        getFocusableChildren(el).forEach(function (child) {
            child.setAttribute('tabindex', focusable ? '0' : '-1');
        });
    }


    var A11Y_MAIN_SELECTOR = 'main, [role="main"], #main-content, #content';

    var A11Y_HIDDEN_LAYER_SELECTOR = [
        '.hpv-search-panel',
        '.search-overlay',
        '.hapvida-sb__dropdown-wrap .dropdown-menu'
    ].join(',');

    var A11Y_SEARCH_TRIGGER_GUARD = [
        '.hpv-search-btn',
        '.hapvida-sb__search-btn',
        '.hapvida-search-btn',
        '.search-button',
        '.search-toggle',
        '[data-search-trigger]'
    ].join(',');

    function a11yIsHidden(el) {
        if (!el.getClientRects().length) {
            return true;
        }

        var style = window.getComputedStyle(el);

        if (style.visibility === 'hidden' || parseFloat(style.opacity) === 0) {
            return true;
        }

        var rect = el.getBoundingClientRect();

        return rect.width === 0 ||
            rect.height === 0 ||
            rect.right <= 0 ||
            rect.left >= window.innerWidth;
    }

    function initSkipLink() {
        if (document.querySelector('.a11y-skip-link')) {
            return;
        }

        var target = document.querySelector(A11Y_MAIN_SELECTOR);

        if (!target) {
            return;
        }

        if (!target.id) {
            target.id = 'main-content';
        }

        if (!target.hasAttribute('tabindex')) {
            target.setAttribute('tabindex', '-1');
        }

        var style = document.createElement('style');
        style.textContent =
            '.a11y-skip-link{position:fixed;top:8px;left:8px;z-index:100000;padding:12px 20px;' +
            'background:#000;color:#fff;font:600 16px/1.2 sans-serif;border-radius:4px;' +
            'text-decoration:none;transform:translateY(-200%);}' +
            '.a11y-skip-link:focus{transform:translateY(0);outline:3px solid #ffbf47;outline-offset:2px;}';
        document.head.appendChild(style);

        var link = document.createElement('a');
        link.className = 'a11y-skip-link';
        link.href = '#' + target.id;
        link.textContent = 'Pular para o conteúdo';

        link.addEventListener('click', function (e) {
            e.preventDefault();
            target.focus();
            target.scrollIntoView();
        });

        document.body.insertBefore(link, document.body.firstChild);
    }

    function syncHiddenLayers() {
        document.querySelectorAll(A11Y_HIDDEN_LAYER_SELECTOR).forEach(function (layer) {
            if (layer.querySelector(A11Y_SEARCH_TRIGGER_GUARD)) {
                return;
            }

            var hidden = a11yIsHidden(layer);

            if (hidden && !layer.contains(document.activeElement)) {
                layer.setAttribute('inert', '');
            }
            else if (!hidden) {
                layer.removeAttribute('inert');
            }
        });
    }

    function fixVLibras() {
        var btn = document.querySelector('[vw-access-button]');

        if (!btn) {
            return;
        }

        if (btn.getAttribute('tabindex') !== '0') {
            btn.setAttribute('tabindex', '0');
        }

        if (!btn.hasAttribute('role')) {
            btn.setAttribute('role', 'button');
        }

        if (!btn.hasAttribute('aria-label')) {
            btn.setAttribute('aria-label', 'Ativar VLibras, tradutor de Libras');
        }

        if (btn.dataset.a11yBound === 'true') {
            return;
        }

        btn.dataset.a11yBound = 'true';

        btn.addEventListener('keydown', function (e) {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
                e.preventDefault();
                btn.click();
            }
        });

        new MutationObserver(function () {
            if (btn.getAttribute('tabindex') !== '0') {
                btn.setAttribute('tabindex', '0');
            }
        }).observe(btn, { attributes: true, attributeFilter: ['tabindex'] });
    }

    function initGlobalA11y() {
        if (window.__headerA11yReady) {
            return;
        }

        window.__headerA11yReady = true;

        initSkipLink();

        var timer = null;

        function scheduleSync() {
            clearTimeout(timer);

            timer = setTimeout(function () {
                syncHiddenLayers();
                fixVLibras();
            }, 60);
        }

        function releaseThenSync() {
            document.querySelectorAll(A11Y_HIDDEN_LAYER_SELECTOR).forEach(function (layer) {
                layer.removeAttribute('inert');
            });

            setTimeout(syncHiddenLayers, 400);
        }

        document.addEventListener('click', releaseThenSync, true);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Enter' || e.key === ' ') {
                releaseThenSync();
            }
        }, true);

        document.addEventListener('transitionend', scheduleSync, true);
        window.addEventListener('resize', scheduleSync);
        window.addEventListener('load', scheduleSync);

        new MutationObserver(scheduleSync).observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['class', 'style', 'hidden', 'aria-expanded']
        });

        scheduleSync();
    }

    // MENU PRINCIPAL
    function initHeaderMenu(header) {
        if (!header || header.dataset.headerMenuReady === 'true') {
            return;
        }

        header.dataset.headerMenuReady = 'true';

        var hamburger = header.querySelector('.nav-hamburger');
        var container = header.querySelector('.navigation-container');

        if (!hamburger || !container) {
            return;
        }

        updateAriaLabels(header);

        function isMobile() {
            return window.innerWidth <= 991;
        }

        var openGroup = null;
        var openSecondaryGroup = null;
        var desktopOpenGroups = new Set();

        function syncDrawerFocus() {
            var blocked = isMobile() && !container.classList.contains('is-open');

            if (blocked) {
                if (container.contains(document.activeElement)) {
                    hamburger.focus();
                }

                container.setAttribute('inert', '');
            }
            else {
                container.removeAttribute('inert');
            }
        }

        var SEARCH_TRIGGER_SELECTOR = [
            '.hpv-search-btn',
            '.hapvida-sb__search-btn',
            '.hapvida-search-btn',
            '.search-button',
            '.search-toggle',
            '.search-icon',
            '[data-search-trigger]',
            '[aria-label="Pesquisar"]',
            '[aria-label="Abrir pesquisa"]',
            '[aria-label="Abrir busca"]'
        ].join(',');

        var SEARCH_AREA_SELECTOR = [
            '.hpv-search',
            '.hpv-search-panel',
            '.hapvida-sb',
            '.hapvida-sb__dropdown-wrap',
            '.search-overlay',
            '.search-wrapper',
            '.search-container',
            '.search-bar',
            '[data-search-layer]'
        ].join(',');

        var DROPDOWN_TRIGGER_SELECTOR = [
            '[data-toggle="dropdown"]',
            '[data-bs-toggle="dropdown"]',
            '.dropdown-toggle'
        ].join(',');

        function isVisible(el) {
            return !!(el && (el.offsetWidth || el.offsetHeight || el.getClientRects().length));
        }

        function closeBootstrapDropdowns(exceptTarget) {
            var exceptRoot = exceptTarget
                ? exceptTarget.closest(
                    '.dropdown, ' +
                    '.hapvida-sb__dropdown-wrap, ' +
                    '.hpv-search, ' +
                    '.search-wrapper, ' +
                    '.search-container'
                )
                : null;

            document.querySelectorAll(DROPDOWN_TRIGGER_SELECTOR).forEach(function (toggle) {
                if (exceptRoot && exceptRoot.contains(toggle)) {
                    return;
                }

                try {
                    if (window.bootstrap && window.bootstrap.Dropdown) {
                        var instance = window.bootstrap.Dropdown.getInstance(toggle);

                        if (instance) {
                            instance.hide();
                        }
                    }

                    if (window.jQuery && window.jQuery.fn && window.jQuery.fn.dropdown) {
                        window.jQuery(toggle).dropdown('hide');
                    }
                }
                catch (e) {}

                toggle.setAttribute('aria-expanded', 'false');
            });

            document.querySelectorAll('.dropdown-menu.show').forEach(function (menu) {
                if (exceptRoot && exceptRoot.contains(menu)) {
                    return;
                }

                menu.classList.remove('show');
                menu.style.removeProperty('display');
            });

            document.querySelectorAll('.dropdown.show').forEach(function (dropdown) {
                if (exceptRoot && exceptRoot.contains(dropdown)) {
                    return;
                }

                dropdown.classList.remove('show');
            });
        }

        function closeSearchLayer() {
            document.dispatchEvent(new CustomEvent('hapvida:close-search'));

            document.querySelectorAll(
                '.hpv-search-close, ' +
                '.hapvida-sb__close, ' +
                '.search-close, ' +
                '[aria-label="Fechar pesquisa"], ' +
                '[aria-label="Fechar busca"], ' +
                '[aria-label="Limpar pesquisa"], ' +
                '[aria-label="Limpar busca"]'
            ).forEach(function (button) {
                if (isVisible(button)) {
                    button.click();
                }
            });

            document.querySelectorAll(
                '.hpv-search-panel.show, ' +
                '.hpv-search-panel.visible, ' +
                '.hpv-search-panel.is-open, ' +
                '.search-overlay.show, ' +
                '.search-overlay.visible, ' +
                '.search-overlay.is-open, ' +
                '.search-wrapper.show, ' +
                '.search-wrapper.visible, ' +
                '.search-wrapper.is-open, ' +
                '.search-container.show, ' +
                '.search-container.visible, ' +
                '.search-container.is-open, ' +
                '.hapvida-sb__dropdown-wrap .dropdown-menu.show'
            ).forEach(function (layer) {
                layer.classList.remove('show', 'visible', 'is-open', 'open', 'active');
                layer.style.removeProperty('display');
            });

            document.querySelectorAll(SEARCH_TRIGGER_SELECTOR).forEach(function (trigger) {
                trigger.setAttribute('aria-expanded', 'false');
            });
        }

        function initSubmenuTabIndex() {
            container.querySelectorAll('.submenu, .sub-submenu').forEach(function (submenu) {
                setFocusable(submenu, false);
            });
        }

        initSubmenuTabIndex();

        function closeAllMobileSubmenus() {
            container.querySelectorAll('.submenu.visible, .sub-submenu.visible').forEach(function (item) {
                item.classList.remove('visible');
                setFocusable(item, false);
            });

            container.querySelectorAll('.primary-link[aria-expanded="true"], .secondary-link.has-children[aria-expanded="true"]').forEach(function (trigger) {
                trigger.setAttribute('aria-expanded', 'false');
            });

            openGroup = null;
            openSecondaryGroup = null;
        }

        function closeDrawer() {
            container.classList.remove('is-open');
            hamburger.setAttribute('aria-expanded', 'false');
            document.body.classList.remove('nav-lock');
            closeAllMobileSubmenus();
            syncDrawerFocus();
        }

        function openDrawer() {
            container.classList.add('is-open');
            hamburger.setAttribute('aria-expanded', 'true');
            document.body.classList.add('nav-lock');
            syncDrawerFocus();
        }

        function closeAnyDesktopSubmenu() {
            if (isMobile()) {
                return;
            }

            document.querySelectorAll('.navigation-container').forEach(function (cont) {
                cont.querySelectorAll('.submenu.visible, .sub-submenu.visible').forEach(function (submenu) {
                    submenu.classList.remove('visible');
                    setFocusable(submenu, false);
                });

                cont.querySelectorAll('.primary-link[aria-expanded="true"], .secondary-link.has-children[aria-expanded="true"]').forEach(function (trigger) {
                    trigger.setAttribute('aria-expanded', 'false');
                });
            });

            desktopOpenGroups.clear();
            openGroup = null;
            openSecondaryGroup = null;
        }

        function closeSubmenu() {
            if (!openGroup) {
                return;
            }

            var submenu = openGroup.querySelector('.submenu');
            var trigger = openGroup.querySelector('.primary-link');

            if (submenu) {
                submenu.classList.remove('visible');
                setFocusable(submenu, false);
            }

            if (trigger) {
                trigger.setAttribute('aria-expanded', 'false');
            }

            desktopOpenGroups.delete(openGroup);
            openGroup = null;
        }

        function closeSubSubmenu() {
            if (!openSecondaryGroup) {
                return;
            }

            var subSubmenu = openSecondaryGroup.parentElement.querySelector('.sub-submenu');

            if (subSubmenu) {
                subSubmenu.classList.remove('visible');
                setFocusable(subSubmenu, false);
            }

            openSecondaryGroup.setAttribute('aria-expanded', 'false');
            openSecondaryGroup = null;
        }

        function closeHeaderMenusForOverlay() {
            closeSubmenu();
            closeSubSubmenu();

            if (isMobile()) {
                closeAllMobileSubmenus();
            }
            else {
                closeAnyDesktopSubmenu();
            }
        }

        // Clique capturado antes dos scripts dos fragments/dropdowns.
        // Isso garante que, ao abrir um elemento, os outros sejam fechados antes.
        document.addEventListener('click', function (event) {
            if (!header.contains(event.target)) {
                return;
            }

            var clickedSearch = event.target.closest(SEARCH_TRIGGER_SELECTOR);
            var clickedSearchArea = event.target.closest(SEARCH_AREA_SELECTOR);
            var clickedMenu = event.target.closest('.primary-link, .secondary-link.has-children, .nav-hamburger');
            var clickedDropdown = event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (clickedSearch || clickedSearchArea) {
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (clickedMenu) {
                closeSearchLayer();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (clickedDropdown) {
                closeSearchLayer();
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
            }
        }, true);

        document.addEventListener('focusin', function (event) {
            if (!header.contains(event.target)) {
                return;
            }

            var focusedSearchArea = event.target.closest(SEARCH_AREA_SELECTOR);
            var focusedMenuTrigger = event.target.closest('.primary-link, .secondary-link.has-children, .nav-hamburger');
            var focusedDropdown = event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (focusedSearchArea) {
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (focusedMenuTrigger) {
                closeSearchLayer();
                closeBootstrapDropdowns(event.target);
                return;
            }

            if (focusedDropdown) {
                closeSearchLayer();
                closeHeaderMenusForOverlay();
                closeBootstrapDropdowns(event.target);
            }
        }, true);

        function getFocusableRoot(group) {
            return (
                group.querySelector('[role="button"].primary-link') ||
                group.querySelector('a.primary-link')
            );
        }

        // CTRL+SHIFT
        container.addEventListener('keydown', function (e) {
            if (isMobile()) return;

            var isCtrlShift = e.ctrlKey && e.shiftKey;
            var isArrowLeft = e.key === 'ArrowLeft';

            if (!isCtrlShift && !isArrowLeft) return;

            var allGroups = Array.from(container.querySelectorAll('.link-group'));
            var currentIndex = -1;

            allGroups.forEach(function (group, idx) {
                if (group.contains(e.target)) {
                    currentIndex = idx;
                }
            });

            if (currentIndex === -1) return;

            if (isCtrlShift) {
                var nextIndex = currentIndex + 1;
                if (nextIndex >= allGroups.length) return;

                var nextFocusable = getFocusableRoot(allGroups[nextIndex]);
                if (!nextFocusable) return;

                e.preventDefault();
                nextFocusable.focus();
            }

            if (isArrowLeft) {
                var prevIndex = currentIndex - 1;
                if (prevIndex < 0) return;

                var prevFocusable = getFocusableRoot(allGroups[prevIndex]);
                if (!prevFocusable) return;

                e.preventDefault();
                prevFocusable.focus();
            }
        });

        function bindGroup(group) {
            if (group.dataset.menuClickBound) {
                return;
            }

            group.dataset.menuClickBound = 'true';

            var trigger = group.querySelector('.primary-link');
            var submenu = group.querySelector('.submenu');

            if (!trigger || !submenu) {
                return;
            }

            function toggle(e) {
                e.preventDefault();
                e.stopPropagation();

                var isExpanded = trigger.getAttribute('aria-expanded') === 'true';

                if (isExpanded) {
                    submenu.classList.remove('visible');
                    setFocusable(submenu, false);
                    trigger.setAttribute('aria-expanded', 'false');
                    desktopOpenGroups.delete(group);

                    if (openGroup === group) {
                        openGroup = null;
                    }

                    return;
                }

                closeSearchLayer();
                closeBootstrapDropdowns();

                if (!isMobile()) {
                    closeAnyDesktopSubmenu();
                }
                else {
                    container.querySelectorAll('.submenu.visible').forEach(function (openSubmenu) {
                        if (openSubmenu !== submenu) {
                            openSubmenu.classList.remove('visible');
                            setFocusable(openSubmenu, false);
                        }
                    });

                    container.querySelectorAll('.primary-link[aria-expanded="true"]').forEach(function (openTrigger) {
                        if (openTrigger !== trigger) {
                            openTrigger.setAttribute('aria-expanded', 'false');
                        }
                    });
                }

                closeSubSubmenu();

                submenu.classList.add('visible');
                setFocusable(submenu, true);
                trigger.setAttribute('aria-expanded', 'true');
                openGroup = group;

                if (!isMobile()) {
                    desktopOpenGroups.add(group);
                }
            }

            function handleKeyDown(e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggle(e);
                }

                if (e.key === 'Escape') {
                    if (isMobile()) {
                        closeDrawer();
                    }
                    else {
                        closeSubmenu();
                        closeSubSubmenu();
                        closeAnyDesktopSubmenu();
                    }
                }
            }

            trigger.addEventListener('click', toggle);
            trigger.addEventListener('keydown', handleKeyDown);

            submenu.querySelectorAll('.secondary-link.has-children').forEach(function (secondaryLink) {
                var subSubmenu = secondaryLink.parentElement.querySelector('.sub-submenu');

                if (!subSubmenu || secondaryLink.dataset.menuClickBound) {
                    return;
                }

                secondaryLink.dataset.menuClickBound = 'true';

                function toggleSub(e) {
                    e.preventDefault();
                    e.stopPropagation();

                    var isExpanded = secondaryLink.getAttribute('aria-expanded') === 'true';

                    if (isExpanded) {
                        subSubmenu.classList.remove('visible');
                        setFocusable(subSubmenu, false);
                        secondaryLink.setAttribute('aria-expanded', 'false');

                        if (openSecondaryGroup === secondaryLink) {
                            openSecondaryGroup = null;
                        }

                        return;
                    }

                    closeSearchLayer();
                    closeBootstrapDropdowns();

                    document.querySelectorAll('.navigation-container .sub-submenu.visible').forEach(function (openSubSubmenu) {
                        if (openSubSubmenu !== subSubmenu) {
                            openSubSubmenu.classList.remove('visible');
                            setFocusable(openSubSubmenu, false);
                        }
                    });

                    document.querySelectorAll('.navigation-container .secondary-link.has-children[aria-expanded="true"]').forEach(function (openTrigger) {
                        if (openTrigger !== secondaryLink) {
                            openTrigger.setAttribute('aria-expanded', 'false');
                        }
                    });

                    subSubmenu.classList.add('visible');
                    setFocusable(subSubmenu, true);
                    secondaryLink.setAttribute('aria-expanded', 'true');
                    openSecondaryGroup = secondaryLink;
                }

                function handleSubKeyDown(e) {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        toggleSub(e);
                    }

                    if (e.key === 'Escape') {
                        if (isMobile()) {
                            closeDrawer();
                        }
                        else {
                            closeSubSubmenu();
                        }
                    }
                }

                secondaryLink.addEventListener('click', toggleSub);
                secondaryLink.addEventListener('keydown', handleSubKeyDown);
            });
        }

        // MOBILE
        var hamburgerIsNative =
            hamburger.tagName === 'BUTTON' ||
            (hamburger.tagName === 'A' && hamburger.hasAttribute('href'));

        if (!hamburgerIsNative) {
            if (!hamburger.hasAttribute('role')) {
                hamburger.setAttribute('role', 'button');
            }

            if (!hamburger.hasAttribute('tabindex')) {
                hamburger.setAttribute('tabindex', '0');
            }
        }

        if (!hamburger.hasAttribute('aria-expanded')) {
            hamburger.setAttribute('aria-expanded', 'false');
        }

        if (container.id && !hamburger.hasAttribute('aria-controls')) {
            hamburger.setAttribute('aria-controls', container.id);
        }

        var lastKeyToggle = 0;

        function toggleDrawer(event) {
            event.preventDefault();
            event.stopPropagation();

            if (event.type === 'click' && Date.now() - lastKeyToggle < 150) {
                return;
            }

            closeSearchLayer();
            closeBootstrapDropdowns();

            if (!isMobile()) {
                return;
            }

            if (container.classList.contains('is-open')) {
                closeDrawer();
            }
            else {
                openDrawer();
            }
        }

        hamburger.addEventListener('click', toggleDrawer);

        hamburger.addEventListener('keydown', function (event) {
            if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {
                lastKeyToggle = Date.now();
                toggleDrawer(event);
            }
        });

        hamburger.addEventListener('keyup', function (event) {
            if (event.key === ' ' || event.key === 'Spacebar') {
                event.preventDefault();
            }
        });

        document.addEventListener('click', function (event) {
            var isClickInsideMenu = container.contains(event.target);
            var isClickOnHamburger = hamburger.contains(event.target);
            var isClickInsideSearch = !!event.target.closest(SEARCH_AREA_SELECTOR);
            var isClickOnSearchTrigger = !!event.target.closest(SEARCH_TRIGGER_SELECTOR);
            var isClickOnDropdown = !!event.target.closest(DROPDOWN_TRIGGER_SELECTOR);

            if (!isClickInsideMenu && !isClickOnHamburger) {
                if (isMobile()) {
                    if (container.classList.contains('is-open') && !isClickInsideSearch && !isClickOnSearchTrigger && !isClickOnDropdown) {
                        closeDrawer();
                    }
                }
                else {
                    if (!isClickInsideSearch && !isClickOnSearchTrigger && !isClickOnDropdown) {
                        closeSubmenu();
                        closeSubSubmenu();
                        closeAnyDesktopSubmenu();
                    }
                }
            }
        });

        document.addEventListener('keydown', function (event) {
            if (event.key === 'Escape') {
                closeSearchLayer();
                closeBootstrapDropdowns();

                if (isMobile() && container.classList.contains('is-open')) {
                    closeDrawer();
                }
                else if (!isMobile()) {
                    closeSubmenu();
                    closeSubSubmenu();
                    closeAnyDesktopSubmenu();
                }
            }
        });

        window.addEventListener('resize', function () {
            if (!isMobile() && container.classList.contains('is-open')) {
                closeDrawer();
            }

            if (!isMobile()) {
                closeAnyDesktopSubmenu();
            }

            closeSearchLayer();
            closeBootstrapDropdowns();
            initSubmenuTabIndex();
            syncDrawerFocus();
        });

        container.querySelectorAll('.link-group').forEach(bindGroup);
        syncDrawerFocus();
    }

    function initAll() {
        initGlobalA11y();
        document.querySelectorAll('.base-header-dropzone').forEach(initHeaderMenu);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    }
    else {
        initAll();
    }

}());;

