/* ============================================================
   Hapvida Search Overlay Fragment
   ============================================================ */

/* Ã‚ncora de altura zero â€” nÃ£o empurra conteÃºdo */
.hso-anchor {
  position: relative;
  height: 0;
  width: 100%;
  overflow: visible;
}

/* --- Overlay container --- */
.hapvida-search-overlay {
  display: flex;
  flex-direction: column;
  align-items: center;

  position: absolute;
  top: -30px;
  left: 50%;
  width: 100%;
  min-height: 140px;

  background-color: #ffffff;
  z-index: 1000;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);

