js:
$(document).ready(function () {
    //  Verifica se a opção "São Paulo" existe no select
    let selectedOption = $(".contacts-fragment-select option").filter(function () {
        return $(this).text() === "São Paulo";
    });

    // Se existir, altera o valor do select para "São Paulo" e dispara o evento de mudança
    if (selectedOption.length > 0) {
        $(".contacts-fragment-select").val(selectedOption.val()).trigger("change");
    }

    // Obtém todas as opções do select
    let $select = $(".contacts-fragment-select");
    let options = $select.find("option").toArray();

    // Ordena as opções alfabética (ignorando o primeiro item "Selecione o Estado")
    let sortedOptions = options.slice(1).sort((a, b) => {
        return $(a).text().localeCompare($(b).text(), 'pt-BR');
    });

    // Reinsere as opções no select, mantendo o primeiro item fixo no topo
    $select.empty().append(options[0]).append(sortedOptions);
});

$(".contacts-fragment-select").on("change", function () {
    let selectedCategoria = $(".contacts-fragment-select").val();
    let resultCounter = 0;

    $('.state-select').find('.contact').each(function () {
        if ($(this).attr('contact-category') !== selectedCategoria && selectedCategoria !== "Resultados") {
            $(this).addClass('d-none');
        } else {
            $(this).removeClass('d-none');
            resultCounter++;
        }
    });

    if (selectedCategoria === "Resultados") {
        $('.contacts-search-result').html(`<p>Resultados</p>`)
    } else {
        $('.contacts-search-result').html(`
                <p>(${resultCounter}) Resultados em ${selectedCategoria}</p>
                ${resultCounter === 0 ? "<p>Não encontramos resultados para esta pesquisa.</p>" : ""}
            `)
    }
});;

