}

.global-main-banner.banner-medium {
    padding: 5rem 0;
}

.global-main-banner.banner-large {
    padding: 6rem 0;
}

.global-main-banner.banner-larger {
    padding: 7rem 0;
}

.global-main-banner.banner-huge {
    padding: 8rem 0;
}

.global-main-banner.banner-gigantic {
    padding: 9rem 0;
}

.global-main-banner
    .main-content{
        display: flex;
        flex-direction: column;
        width: 100%;
        max-width: 1140px;
        z-index: 3;  
}

.global-main-banner
        .background-container{
            display: flex;
            width: 100%;
            height: 100%;
            position: absolute;
}

.global-main-banner
        .background-container
            .mask{
                color: var(--primary);
                width: 60%;
                z-index: 2;
}

.global-main-banner
        .background-container
            img {
                display: block;
                width: 100%;
                height: 100%;
                object-fit: cover;

                z-index: 1;
                right: 0;
                position: absolute;
}

.global-main-banner
    .main-content
        .text-container{
            display: flex;
            flex-direction: column;
            max-width: 565px;
            width: 100%;
