js:
fragmentElement.style.display = 'flex';
fragmentElement.style.justifyContent = 'center';

const videoFragment = document.getElementById(
	"video-" + fragmentNamespace
);


function createIframe() {
    const embedUrl = configuration.url.replace('watch?v=', 'embed/').concat('?controls=0&modestbranding=1&rel=0&autoplay=1');

	const iframe = document.createElement('iframe');
    iframe.width = "100%";
    iframe.height = "100%";
	iframe.src = embedUrl;
	iframe.title = "YouTube video player";
	iframe.frameBorder = "0";
	iframe.allow = "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture;";
	iframe.allowFullscreen = true;
	iframe.id = "youtube-player";

	videoFragment.appendChild(iframe);	
}

function addThumbnailToContainer(youtubeUrl) {
    videoFragment.querySelector('.blank-thumbnail').remove();

    const regex = /(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const match = youtubeUrl.match(regex);
    if (match) {
        const thumbnailUrl = `https://img.youtube.com/vi/${match[1]}/sddefault.jpg`;

        const videoThumbnail = document.createElement("img");
        videoThumbnail.classList.add("youtube-thumbnail");
        videoThumbnail.src = thumbnailUrl;

        const thumbnailActionButton = document.createElement("div");
        thumbnailActionButton.classList.add("thumbnail-action-button");
        thumbnailActionButton.setAttribute("tabindex", "0"); 

        const svgColor = configuration.buttonColor === "default" ? "#f00" : "#000";

        const svgPlayButton = `
            <svg height="100%" version="1.1" viewBox="0 0 68 48" width="100%">
                <path class="ytp-large-play-button-bg" d="M66.52,7.74c-0.78-2.93-2.49-5.41-5.42-6.19C55.79,.13,34,0,34,0S12.21,.13,6.9,1.55 C3.97,2.33,2.27,4.81,1.48,7.74C0.06,13.05,0,24,0,24s0.06,10.95,1.48,16.26c0.78,2.93,2.49,5.41,5.42,6.19 C12.21,47.87,34,48,34,48s21.79-0.13,27.1-1.55c2.93-0.78,4.64-3.26,5.42-6.19C67.94,34.95,68,24,68,24S67.94,13.05,66.52,7.74z" fill="${svgColor}"></path>
                <path d="M 45,24 27,14 27,34" fill="#fff"></path>
            </svg>
        `;

        thumbnailActionButton.innerHTML = svgPlayButton;
        videoFragment.appendChild(videoThumbnail);
        videoFragment.appendChild(thumbnailActionButton);

        const playVideo = () => {
            videoThumbnail.style.display = "none";
            thumbnailActionButton.style.display = "none";
            createIframe();
        };

        thumbnailActionButton.addEventListener("click", (e) => {
            e.preventDefault();
            playVideo();
        });

        thumbnailActionButton.addEventListener("keydown", (e) => {
            if (e.key === "Enter") {
                e.preventDefault();
                playVideo();
            }
        });

    } else {
        console.error('Invalid YouTube URL.');
    }
}

if(configuration.url != ""){
    addThumbnailToContainer(configuration.url);
};

