const fragmentContainer = fragmentElement.querySelector('.global-banner-dinamic-intern-pages');
const container = fragmentContainer.querySelector(".buttons-container");
const interactiveElements = container.querySelectorAll("[id]");

const buttons = [];
const groups = [];

if (!document.body.classList.contains("has-edit-mode-menu")) {
    // Classificação com base no ID
    interactiveElements.forEach(el => {
        if (el.id.startsWith("button-") && !el.id.includes("group")) {
            buttons.push(el);
        } else if (el.id.startsWith("group-") ||
                    (el.id.startsWith("button-") && el.id.includes("group"))) {
            groups.push(el);
        }
    });

    // Função para mostrar grupo e ativar botão
    function ativarGrupo(grupoId, botaoClicado) {
        // Remove active de todos os grupos e botões
        groups.forEach(gp => gp.classList.remove("active"));
        buttons.forEach(btn => btn.classList.remove("active"));

        botaoClicado.classList.add("active");
        document.getElementById(grupoId).classList.add("active");
        container.classList.add("group-open");
    }

    // Função para resetar tudo
    function resetarGrupo() {
        groups.forEach(gp => gp.classList.remove("active"));
        buttons.forEach(btn => btn.classList.remove("active"));
        container.classList.remove("group-open");
    }

    buttons.forEach(btn => {
        // Clique com mouse
        btn.addEventListener("click", (event) => {
            event.stopPropagation();
            const numero = btn.id.split("-")[1];
            const grupoId = `group-${numero}`;
            ativarGrupo(grupoId, btn);
        });

        // Ativação via teclado (Enter)
        btn.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                const numero = btn.id.split("-")[1];
                const grupoId = `group-${numero}`;
                ativarGrupo(grupoId, btn);
            }
        });
    });

    // Clique fora do fragmentContainer reseta tudo
    document.addEventListener("click", (event) => {
        if (!fragmentContainer.contains(event.target)) {
            resetarGrupo();
        }
    });

    // Foco (tabbing) fora do fragmentContainer reseta tudo
    document.addEventListener("focusin", (event) => {
        if (!fragmentContainer.contains(event.target)) {
            resetarGrupo();
        }
    });
};

const fragmentContainer = fragmentElement.querySelector(
  ".global-whatsapp-forwarding"
);
const whatsappForwardingElement = fragmentContainer.querySelector(
  "#whatsapp-forwarding"
);

if (whatsappForwardingElement) {
  const handleWhatsAppForwarding = () => {
    const rawPhone = configuration.forwardingNumber || "";
    let phone = rawPhone.replace(/\D/g, "").replace(/^0+/, "");

    if (!phone.startsWith("55")) {
      phone = "55" + phone;
    }

    const message = configuration.forwardingMessage;

    if (phone.length >= 12) {
      let url = `https://wa.me/${phone}`;
      if (message) {
        url += `?text=${encodeURIComponent(message)}`;
      }
      window.open(url, "_blank");
    }
  };

  whatsappForwardingElement.addEventListener("click", handleWhatsAppForwarding);

  whatsappForwardingElement.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.keyCode === 13) {
      handleWhatsAppForwarding();
    }
  });

  whatsappForwardingElement.setAttribute("tabindex", "0");
  whatsappForwardingElement.style.cursor = "pointer";
};

