display:flex;
}
.cardsQualiServicos .slick-slide{
height:auto;
}
.cardsQualiServicos .blocoQualiTexto {
display: flex;
flex-direction: column;
height: 100%;
}

.cardsQualiServicos .arrow_prevQuali span, .cardsQualiServicos .arrow_nextQuali span{
display: inline-block;
width: 30px;
height: 30px;
line-height:26px;
background-color: #2D2D2D;
overflow:hidden;
cursor: pointer;
}

.cardsQualiServicos .sliderQualiServicos .blocoQuali{
background: #FFFFFF 0% 0% no-repeat padding-box;
box-shadow: 0px 3px 6px #0000004A;
border-radius: 3px;
min-height: 191px;
width:100%;
}

/*Custom slick*/
.cardsQualiServicos .arrow_prevQuali, .cardsQualiServicos .arrow_nextQuali {
position: absolute;
bottom: 50%;
border: none;
background: transparent;
height:30px;
padding:2px;
}
.cardsQualiServicos button:focus-visible, .cardsQualiServicos button:focus-visible{
outline: auto!important;
}
.cardsQualiServicos button:focus{
outline-width: medium;
outline-style: none;
outline-color: invert;
}
.cardsQualiServicos .arrow_nextQuali {
right: -3%;
}
.cardsQualiServicos .arrow_prevQuali{
right: initial;
left: -3%;
}

.cardsQualiServicos .sliderQualiServicos .slick-dots li button:before{
font-size: 12px;
}
.cardsQualiServicos .sliderQualiServicos .slick-dots li.slick-active button:before{
color:#0054B8;
font-size: 12px;
background-color: var(--primary)!important;
border-radius: 2px;
opacity:1;
}

.cardsQualiServicos .arrow_prevQuali.slick-arrow.slick-disabled, .cardsQualiServicos .arrow_nextQuali.slick-arrow.slick-disabled{
opacity:0.25;
}
.cardsQualiServicos .arrow_prevQuali,
.cardsQualiServicos .arrow_nextQuali {
display: none;
}

.cardsQualiServicos .sliderQualiServicos .slick-dots li button:before{
border: 1px solid var(--primary)!important;
content:"";
border-radius: 2px;
width: 15px;
height: 15px;
}
.cardsQualiServicos .sliderQualiServicos .slick-dots li button:hover:before, .cardsQualiServicos .sliderQualiServicos .slick-dots li button:focus:before{
color:initial;
}

.cardsQualiServicos .sliderQualiServicos .slick-dots{
