if(configuration.hasDropzone === true) {
    const fragmentContainer = fragmentElement.querySelector('.global-steps-with-icon');
    const stepButtons = fragmentContainer.querySelectorAll('.button-container');
    const stepContents = fragmentContainer.querySelectorAll('.step-content');

    function setDefaultTab() {
        stepButtons[0]?.classList.add('active');
        stepContents[0]?.classList.add('active');
    }

    function switchTab(button) {
        stepButtons.forEach(btn => btn.classList.remove('active'));
        stepContents.forEach(content => content.classList.remove('active'));

        button.classList.add('active');
        const targetTab = fragmentContainer.querySelector(`#${button.getAttribute('data-tab')}`);
        targetTab?.classList.add('active');
    }

    stepButtons.forEach(button => {
        button.addEventListener('click', () => switchTab(button));
        button.addEventListener('touchstart', () => switchTab(button));
    });

    setDefaultTab();
};

