    grid-template-columns: 3fr 4fr;
}

.global-dropzone-more-text.first-col-3.second-col-5 {
    grid-template-columns: 3fr 5fr;
}

.global-dropzone-more-text.first-col-3.second-col-6 {
    grid-template-columns: 3fr 6fr;
