                <p><strong>Telefone:</strong> ${formData.telefone || ""}</p>
                <p><strong>Tipo de denúncia:</strong> ${formData.tipoDenuncia || ""}</p>
                <p><strong>Data da ocorrência:</strong> ${formData.dataOcorrencia || ""}</p>
                <p><strong>Local / Unidade envolvida:</strong> ${formData.localUnidade || ""}</p>
                <p><strong>Nomes dos envolvidos:</strong> ${formData.nomesEnvolvidos || ""}</p>
                <p><strong>Como prefere ser contatado:</strong> ${formData.contatoPreferido || "Não informado"}</p>
                <p><strong>Possui evidências:</strong> ${formData.possuiEvidencias || "Não informado"}</p>
                <p><strong>Denúncia:</strong> ${formData.mensagem || ""}</p>
                <p><strong>URL Página:</strong> ${window.location.href}</p>
            </div>
        </body>
    `;

            const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

            const data = {
                to: configuration.emailTo || "",
                subject: subject,
                body: cleanTemplate
            };

            const fileInput = formElement.querySelector('#arquivoDenuncia');
            const file = fileInput?.files?.[0];

            const liberarBotao = () => {
                if (submitBtn) {
                    submitBtn.disabled = false;
                    submitBtn.textContent = "Enviar";
                }
            };

            const enviarDenuncia = () => {
                const apiURL = window.location.origin.toString() + "/api/servicos/email/enviar";

                fetch(apiURL, {
                    method: "POST",
                    headers: {
                        "Accept": "application/json",
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify(data)
                })
                    .then((response) => {
                        formValidator.handleFormResponse(response, successMessage, formContainer, formElement, 5000);

                        if (!response || response.status !== 200) {
                            liberarBotao();
                        }

                        return response;
                    })
                    .catch((error) => {
                        console.error("Erro:", error);
                        liberarBotao();
                    });
            };

            if (file) {
                const reader = new FileReader();

                reader.onload = function () {
                    const result = reader.result || "";
                    const base64 = String(result).split(",")[1];

                    data.attachments = [{
                        fileName: file.name,
                        contentType: file.type,
                        content: base64
                    }];

                    enviarDenuncia();
                };

                reader.onerror = function () {
                    console.error("Erro ao ler arquivo.");
                    liberarBotao();
                };

                reader.readAsDataURL(file);
            } else {
                enviarDenuncia();
            }
        }
    }

    this.handleFormResponse = function (response, successMessage, formTitle, formElement, timeout = 5000) {
        if (response && response.status === 200) {
            if (successMessage && configuration.formModel == "denunciaForm") {
                document.querySelector('.form-title').style.display = 'none';
                successMessage.innerHTML = `
                <img src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2221.686%22%20height%3D%2221.686%22%3E%3Cpath%20d%3D%22M10.843%2021.686A10.843%2010.843%200%201%200%200%2010.843a10.843%2010.843%200%200%200%2010.843%2010.843Z%22%20fill%3D%22%2333ab5f%22%2F%3E%3Cpath%20d%3D%22m8.583%2016.152-4.519-4.519%201.582-1.581%202.937%202.937%207.456-7.456%201.582%201.582Z%22%20fill%3D%22%23fff%22%2F%3E%3C%2Fsvg%3E"
                    alt="Mensagem Sucesso" tabindex="0">

                <div class="message-text">
                    <span class="title oxygen-h3-bold" tabindex="0">
                        Sua denúncia foi enviada com sucesso!
                    </span>
                    <span class="description oxygen-p2-regular " tabindex="0">
                        Obrigada por seu envio, por favor aguarde nosso contato.
                    </span>
                </div>
            `;
            }

            if (successMessage) successMessage.style.display = 'flex';
            if (formTitle) formTitle.style.display = 'none';
            if (formElement) formElement.style.display = 'none';
            if (formElement) formElement.reset();
            const uploadBox = formElement.querySelector('#uploadBox');
            const preview = formElement.querySelector('#uploadPreview');
            const fileInput = formElement.querySelector('#arquivoDenuncia');
            const fileName = formElement.querySelector('#uploadFileName');
            const fileSize = formElement.querySelector('#uploadFileSize');
            const fileExt = formElement.querySelector('#uploadFileExt');

            if (fileInput) fileInput.value = '';

            if (preview) preview.style.display = 'none';
            if (uploadBox) uploadBox.style.display = 'flex';

            if (fileName) fileName.textContent = '';
            if (fileSize) fileSize.textContent = '';
            if (fileExt) fileExt.textContent = '';

            if (configuration.formModel == "pesquisaForm" && formElement) {
                const step1 = formElement.querySelector('.pesquisa-step-1');
                const step2 = formElement.querySelector('.pesquisa-step-2');
                const pfFields = formElement.querySelector('.pesquisa-fields-pf');
                const pjFields = formElement.querySelector('.pesquisa-fields-pj');
                const tipoPessoaHidden = formElement.querySelector('#tipoPessoa');

                if (step2) step2.style.display = 'none';
                if (step1) step1.style.display = 'block';

                if (pfFields) pfFields.style.display = 'none';
                if (pjFields) pjFields.style.display = 'none';

                if (tipoPessoaHidden) tipoPessoaHidden.value = '';

                pfFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });

                pjFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });
            }

            if (recaptchaReady) {
                try {
                    window.grecaptcha.reset();
                    if (submitBtn) submitBtn.disabled = true;
                } catch (e) { }
            } else {
                if (submitBtn) submitBtn.disabled = false;
            }

            if (submitBtn) {
                submitBtn.textContent = 'Enviar';
            }

            setTimeout(() => {
                if (successMessage) successMessage.style.display = 'none';
                if (formTitle) formTitle.style.display = 'inline';
                if (formElement) formElement.style.display = 'flex';

                if (submitBtn) {
                    submitBtn.textContent = 'Enviar';
                    submitBtn.disabled = recaptchaReady ? true : false;
                }
            }, timeout);

            return true;
        }

        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Enviar';
        }

        return false;
    };
}

const formValidator = new FormValidator();

loadRecaptchaSafely({ timeoutMs: 2500 }).then((ok) => {
    if (ok) {
        setInterval(checkRecaptcha, 500);
    } else {
        if (submitBtn) submitBtn.disabled = false;
    }
});

