                        fileName: file.name,
                        contentType: file.type,
                        content: base64
                    }];

                    enviarDenuncia();
                };

                reader.onerror = function () {
                    console.error("Erro ao ler arquivo.");
                    liberarBotao();
                };

                reader.readAsDataURL(file);
