    this.handleFormResponse = function (response, successMessage, formTitle, formElement, timeout = 5000) {
        if (response && response.status === 200) {
            if (successMessage && configuration.formModel == "denunciaForm") {
                document.querySelector('.form-title').style.display = 'none';
                successMessage.innerHTML = `
                <img src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2221.686%22%20height%3D%2221.686%22%3E%3Cpath%20d%3D%22M10.843%2021.686A10.843%2010.843%200%201%200%200%2010.843a10.843%2010.843%200%200%200%2010.843%2010.843Z%22%20fill%3D%22%2333ab5f%22%2F%3E%3Cpath%20d%3D%22m8.583%2016.152-4.519-4.519%201.582-1.581%202.937%202.937%207.456-7.456%201.582%201.582Z%22%20fill%3D%22%23fff%22%2F%3E%3C%2Fsvg%3E"
                    alt="Mensagem Sucesso" tabindex="0">

                <div class="message-text">
                    <span class="title oxygen-h3-bold" tabindex="0">
                        Sua denúncia foi enviada com sucesso!
                    </span>
                    <span class="description oxygen-p2-regular " tabindex="0">
                        Obrigada por seu envio, por favor aguarde nosso contato.
                    </span>
                </div>
            `;
            }

            if (successMessage) successMessage.style.display = 'flex';
            if (formTitle) formTitle.style.display = 'none';
            if (formElement) formElement.style.display = 'none';
            if (formElement) formElement.reset();
            const uploadBox = formElement.querySelector('#uploadBox');
            const preview = formElement.querySelector('#uploadPreview');
            const fileInput = formElement.querySelector('#arquivoDenuncia');
            const fileName = formElement.querySelector('#uploadFileName');
            const fileSize = formElement.querySelector('#uploadFileSize');
            const fileExt = formElement.querySelector('#uploadFileExt');

            if (fileInput) fileInput.value = '';

            if (preview) preview.style.display = 'none';
            if (uploadBox) uploadBox.style.display = 'flex';

            if (fileName) fileName.textContent = '';
            if (fileSize) fileSize.textContent = '';
            if (fileExt) fileExt.textContent = '';

            if (configuration.formModel == "pesquisaForm" && formElement) {
                const step1 = formElement.querySelector('.pesquisa-step-1');
                const step2 = formElement.querySelector('.pesquisa-step-2');
                const pfFields = formElement.querySelector('.pesquisa-fields-pf');
                const pjFields = formElement.querySelector('.pesquisa-fields-pj');
                const tipoPessoaHidden = formElement.querySelector('#tipoPessoa');

                if (step2) step2.style.display = 'none';
                if (step1) step1.style.display = 'block';

                if (pfFields) pfFields.style.display = 'none';
                if (pjFields) pjFields.style.display = 'none';

                if (tipoPessoaHidden) tipoPessoaHidden.value = '';

                pfFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });

                pjFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });
            }

            if (recaptchaReady) {
                try {
                    window.grecaptcha.reset();
                    if (submitBtn) submitBtn.disabled = true;
                } catch (e) { }
            } else {
                if (submitBtn) submitBtn.disabled = false;
            }

            if (submitBtn) {
                submitBtn.textContent = 'Enviar';
            }

            setTimeout(() => {
                if (successMessage) successMessage.style.display = 'none';
                if (formTitle) formTitle.style.display = 'inline';
                if (formElement) formElement.style.display = 'flex';

                if (submitBtn) {
                    submitBtn.textContent = 'Enviar';
                    submitBtn.disabled = recaptchaReady ? true : false;
                }
            }, timeout);

            return true;
        }

        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Enviar';
        }

        return false;
    };
}

const formValidator = new FormValidator();

loadRecaptchaSafely({ timeoutMs: 2500 }).then((ok) => {
    if (ok) {
        setInterval(checkRecaptcha, 500);
    } else {
        if (submitBtn) submitBtn.disabled = false;
    }
});

if (configuration.formModel == "contactForm") {
    formValidator.validateForm('contactForm');
} else if (configuration.formModel == "supplier") {
    formValidator.validateForm('supplier');
} else if (configuration.formModel == "ourPlans") {
    formValidator.validateForm('ourPlans');
} else if (configuration.formModel == "ourPlansGNDI") {
    formValidator.validateForm('ourPlansGNDI');
} else if (configuration.formModel == "endometrioseForm") {
    formValidator.validateForm('endometrioseForm');
} else if (configuration.formModel == "saudementalForm") {
    formValidator.validateForm('saudementalForm');
} else if (configuration.formModel == "pesquisaForm") {
    setupPesquisaForm();
    formValidator.validateForm('pesquisaForm');
} else if (configuration.formModel == "denunciaForm") {
    formValidator.validateForm('denunciaForm');
}

(function () {
    function initfragmentReady() {
        const tipoDenunciaSelect = fragmentElement.querySelector('#tipoDenuncia');
        if (
            configuration.formModel === 'denunciaForm' &&
            tipoDenunciaSelect &&
            tipoDenunciaSelect.dataset.loaded !== 'true'
        ) {
            tipoDenunciaSelect.dataset.loaded = 'true';

            tipoDenunciaSelect.innerHTML = '<option value="">Selecione</option>';

            TIPOS_DENUNCIA.forEach(tipo => {
                const option = document.createElement('option');
                option.value = tipo;
                option.textContent = tipo;
                tipoDenunciaSelect.appendChild(option);
            });
        }
        const localUnidadeSelect = fragmentElement.querySelector('#localUnidade');
        if (
            configuration.formModel === 'denunciaForm' &&
            localUnidadeSelect &&
            localUnidadeSelect.dataset.loaded !== 'true'
        ) {
            localUnidadeSelect.dataset.loaded = 'true';

            localUnidadeSelect.innerHTML = '<option value="">Selecione</option>';

            UNIDADE_ENVOLVIDA.forEach(tipo => {
                const option = document.createElement('option');
                option.value = tipo;
                option.textContent = tipo;
                localUnidadeSelect.appendChild(option);
            });
        }

        const inputsQ = fragmentElement.querySelectorAll("#quntasVidas");
        inputsQ.forEach(function (input) {
            if (input.dataset.onlyNumbersBound === 'true') return;
            input.dataset.onlyNumbersBound = 'true';

            input.addEventListener("input", function () {
                this.value = this.value.replace(/[^0-9]/g, "");
            });
        });

        const inputsNome = fragmentElement.querySelectorAll("#nome, #nomePf, #nomePj");
        inputsNome.forEach(function (input) {
            if (input.dataset.onlyNameBound === 'true') return;
            input.dataset.onlyNameBound = 'true';

            input.addEventListener("input", function () {
                this.value = this.value.replace(/\d+/g, "");
            });

            input.addEventListener("paste", function () {
                setTimeout(() => {
                    this.value = this.value.replace(/\d+/g, "");
                }, 0);
            });
        });

        const ufField = fragmentElement.querySelector("#uf");
        const cidadeSelect = fragmentElement.querySelector("#cidade");

        if (ufField && cidadeSelect && ufField.dataset.cityLoaderBound !== 'true') {
            ufField.dataset.cityLoaderBound = 'true';

            ufField.addEventListener("change", function () {
                const uf = this.value;

                cidadeSelect.disabled = true;
                cidadeSelect.innerHTML = '<option value="">Carregando...</option>';

                if (!uf) {
                    cidadeSelect.innerHTML = '<option value="">Selecione</option>';
                    cidadeSelect.disabled = true;
                    return;
                }

                fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${uf}/municipios`)
                    .then(response => response.json())
                    .then(cidades => {
                        cidadeSelect.innerHTML = '<option value="">Selecione</option>';
                        cidadeSelect.disabled = false;

                        cidades.sort((a, b) => a.nome.localeCompare(b.nome));

                        cidades.forEach(cidade => {
                            const option = document.createElement("option");
                            option.value = cidade.nome;
                            option.textContent = cidade.nome;
                            cidadeSelect.appendChild(option);
                        });
                    })
                    .catch(() => {
                        cidadeSelect.innerHTML = '<option value="">Erro ao carregar</option>';
                        cidadeSelect.disabled = true;
                    });
            });
        }

        const root = fragmentElement || document;
        const els = root.querySelectorAll('[data-toggle="tooltip"]:not([data-tooltip-initialized="true"])');

        els.forEach((el) => {
            el.setAttribute('data-tooltip-initialized', 'true');

            if (window.bootstrap && bootstrap.Tooltip) {
                new bootstrap.Tooltip(el);
                return;
            }

            if (window.$ && $.fn && $.fn.tooltip) {
                $(el).tooltip();
            }
        });

        if (configuration.formModel == "pesquisaForm") {
            setupPesquisaForm();
        }
    }

    document.addEventListener('DOMContentLoaded', initfragmentReady);
    Pagina.on('endNavigate', initfragmentReady);
})();;

