(function () {
  const form = document.getElementById("accessForm");
  const cardForm = document.getElementById("cardForm");
  const sucessMessage = document.getElementById("msgSucesso");

  // Mapeamento para montar payload corretamente
  const fieldMap = {
    nome: "u_bot_nome_contato",
    email: ["u_Email", "u_PJ_email", "emailAddress"],
    telefone: "PhoneNumber",
    cpf: "u_cpf",
    cpfTitular: "u_cpf",
    codigoUsuario: "u_codigoUsuario",
    numeroCarteirinha: "u_carteirinha_beneficiario_atendimento",
    codigoCarteira: "u_carteirinha_beneficiario_atendimento",
    codigoOperadora: ["u_codigoOperadora", "u_PJ_companyPlanCode"],
    cidade: "u_cidadeBeneficiario",
    estado: "u_estado",
    uf: "u_Uf_Beneficiario",
    plano: "u_NomePlano",
    prestador: "u_prestador",
    razaoSocial: ["u_PJ_RazaoSocial", "u_bot_nome_contato"],
    cnpj: "u_cnpj",
    nomeCliente: "u_NomeBeneficiario"
  };

  // Helpers de validação
  const validators = {
    nome: (v) => v.trim().split(" ").length >= 2 || "Digite Nome e Sobrenome",
    prestador: (v) => v.trim().split(" ").length >= 2 || "Digite Nome e Sobrenome",
    email: (v) =>
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || "E-mail inválido",
    telefone: (v) => {
      const numeros = v.replace(/\D/g, ""); // só dígitos
      return /^(\d{10,11})$/.test(numeros) && !/(.)\1{7,}/.test(numeros)
        ? true
        : "Telefone inválido";
    },
    cpf: validateCPF,
    cpfTitular: validateCPF,
    cnpj: validateCNPJ,
    codigoUsuario: (v) =>
      v.length === 16 || "Deve ter 16 caracteres",
    numeroCarteirinha: (v) =>
      /^\d+$/.test(v) || "Apenas números",
    codigoCarteira: (v) =>
      v.length === 16 || "Deve ter 16 caracteres",
    cidade: (v) => v !== "" || "Selecione uma cidade",
    estado: (v) => v !== "" || "Selecione um estado",
    uf: (v) => v !== "" || "Selecione uma UF",
    plano: (v) => v !== "" || "Selecione um plano",
    razaoSocial: (v) =>
      v.trim().length > 0 || "Informe a Razão Social",
cpfCnpj: (v) => {
  const numeros = v.replace(/\D/g, "");

  if (numeros.length === 11) {
    return validateCPF(numeros);
  } 
  if (numeros.length === 14) {
    return validateCNPJ(numeros);
  }

  return "Digite um número de CPF ou CNPJ válido.";
}
  };

  function validateCPF(v) {
    v = v.replace(/\D/g, "");
    if (v.length !== 11 || /^(\d)\1+$/.test(v)) return "CPF inválido";
    let sum = 0;
    for (let i = 0; i < 9; i++) sum += parseInt(v.charAt(i)) * (10 - i);
    let rev = 11 - (sum % 11);
    if (rev === 10 || rev === 11) rev = 0;
    if (rev !== parseInt(v.charAt(9))) return "CPF inválido";
    sum = 0;
    for (let i = 0; i < 10; i++) sum += parseInt(v.charAt(i)) * (11 - i);
    rev = 11 - (sum % 11);
    if (rev === 10 || rev === 11) rev = 0;
    if (rev !== parseInt(v.charAt(10))) return "CPF inválido";
    return true;
  }

  function validateCNPJ(v) {
    v = v.replace(/\D/g, "");
    if (v.length !== 14 || /^(\d)\1+$/.test(v)) return "CNPJ inválido";
    let t = v.length - 2,
      d = v.substring(t),
      d1 = parseInt(d.charAt(0)),
      d2 = parseInt(d.charAt(1)),
      calc = (x) => {
        let n = 0,
          y = x - 7,
          z = 0;
        for (let i = x; i >= 1; i--) {
          n += v.charAt(z++) * y--;
          if (y < 2) y = 9;
        }
        let r = 11 - (n % 11);
        return r > 9 ? 0 : r;
      };
    return calc(t) === d1 && calc(t + 1) === d2 ? true : "CNPJ inválido";
  }

  function getVQ() {
    const urlParams = new URLSearchParams(window.location.search);
    return urlParams.get("vq") || configuration.vqPadrao || "";
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    let isValid = true;
    const payload = {};
    const fields = form.querySelectorAll("input, select");

    let tipoPessoa = null;
    let cpfCnpjValue = null;

    fields.forEach(field => {
      if (field.name === "cpfCnpj" && field.value) {
        const clean = field.value.replace(/\D/g, "");
        cpfCnpjValue = clean;

        if (clean.length === 11) tipoPessoa = "PF";
        if (clean.length === 14) tipoPessoa = "PJ";
      }
    });


    fields.forEach((field) => {
      const name = field.getAttribute("name");
      const value = field.value.trim();
      const feedback = field.parentElement.querySelector(".invalid-feedback");
      const isRequired = field.hasAttribute("required");
      const isCpfCnpjField = name == "cpfCnpj" ? true : false;

      let result = true;

      // Só valida se o campo for obrigatório OU se tiver algum valor preenchido
      if (isRequired && !value) {
        result = "Campo obrigatório";
      } else if (value && validators[name]) {
        // Se tem valor E tem validador específico, valida
        result = validators[name](value);
      }

      if (result !== true) {
        feedback.textContent = result;
        field.classList.add("is-invalid");
        isValid = false;
      } else {
        feedback.textContent = "";
        field.classList.remove("is-invalid");

        // Só adiciona a classe is-valid se o campo tiver valor
        if (value) {
          field.classList.add("is-valid");
        }

        // Adiciona ao payload apenas se tiver valor
        if (value) {

        // CPF / CNPJ
        if (name === "cpfCnpj") {
          if (tipoPessoa === "PF") {
            payload.u_cpf = cpfCnpjValue;
          } else if (tipoPessoa === "PJ") {
            payload.u_cnpj = cpfCnpjValue;
          }
          return;
        }

        // Nome / Razão Social
        if (name === "nomeRazao") {
          payload.u_bot_nome_contato = value;

          if (tipoPessoa === "PJ") {
            payload.u_PJ_RazaoSocial = value;
          }
          return;
        }


          const mapKey = fieldMap[name];
          if (Array.isArray(mapKey)) {
            mapKey.forEach((k) => (payload[k] = value));
          } else if (mapKey) {
            payload[mapKey] = value;
          }
        }
      }
    });

    if (!isValid) return;

    const recaptchaResponse =
      grecaptcha && grecaptcha.getResponse && grecaptcha.getResponse();
    if (!recaptchaResponse) {
      alert("Por favor, confirme o reCAPTCHA.");
      return;
    } else {
      form.classList.add("d-none");
      cardForm.getElementsByClassName("form-title")[0].classList.add("d-none");
      cardForm.getElementsByClassName("form-subtitle")[0].classList.add("d-none");
      sucessMessage.classList.remove("d-none");
    }

    payload["u_vq"] = getVQ();

    console.log("Payload enviado ao Genesys:", payload);
    //payload["recaptcha"] = recaptchaResponse;
    abrirChat(payload);
  });
})();

$(document).ready(function () {
  // Telefone
  $("#telefone").mask("(00) 0000-00009");

  // CPF
  $("#cpf, #cpfTitular").mask("000.000.000-00");

  // CNPJ
