.avih-cardsQualiServicos{
position: relative;
}
.avih-cardsQualiServicos .slick-list{
display:flex;
	width: 100%;
}
.avih-cardsQualiServicos .slick-track{
display:flex;
/*column-gap: 30px;*/
	width:100%;
}
		.avih-cardsQualiServicos .slick-track .avih-blocoQuali + .avih-blocoQuali{
	 margin-left:30px!important;
	}
.avih-cardsQualiServicos .slick-slide{
height:auto;
}
.avih-cardsQualiServicos .avih-blocoQualiTexto {
display: flex;
flex-direction: column;
height: 100%;
}

.avih-cardsQualiServicos .avih-arrow_prevQuali span, .avih-cardsQualiServicos .avih-arrow_nextQuali span{
display: inline-block;
width: 30px;
height: 30px;
line-height:26px;
background-color: #2D2D2D;
overflow:hidden;
cursor: pointer;
}

.avih-cardsQualiServicos .avih-sliderQualiServicos .avih-blocoQuali{
background: #FFFFFF 0% 0% no-repeat padding-box;
box-shadow: 0px 3px 6px #0000004A;
border-radius: 3px;
min-height: 191px;
width:100%;
}

/*Custom slick*/
.avih-cardsQualiServicos .avih-arrow_prevQuali, .avih-cardsQualiServicos .avih-arrow_nextQuali {
position: absolute;
bottom: 50%;
border: none;
background: transparent;
height:30px;
padding:2px;
}
.avih-cardsQualiServicos button:focus-visible, .avih-cardsQualiServicos button:focus-visible{
outline: auto!important;
}
.avih-cardsQualiServicos button:focus{
