    flex-wrap: wrap;
    gap: 20px;
    margin: 40px 0;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-card {
    display: flex;
    flex-direction: column; 
    flex: 1 1 22%;
    min-width: 220px;
	  padding: 20px 4px;
    box-sizing: border-box;
    text-align: center;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-card h2 {
    font-size: 16px;
    margin: 0 0 15px 0;
    font-family: "oxygen-bold";
    color: #2D2D2D;
	  text-align:left;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-body {
    display: flex;
    align-items: center;
    gap: 15px;
    text-align: left;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-icon {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    overflow: hidden;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-icon img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-text p {
    font-size: 12px;
    margin: 0;
    color: #2D2D2D;
    font-family: "oxygen-regular";
}
