const navHeader = document.querySelector('.privacyBen-container .nav-header');
const navBox = document.querySelector('.privacyBen-container .nav-box');

if (navHeader) {
	navHeader.addEventListener('click', function () {
		navBox.classList.toggle('open');
	});
}

document.querySelectorAll('.privacyBen-container .nav-list a')
.forEach(link => {
	link.addEventListener('click', function () {

		document.querySelectorAll('.nav-list li')
			.forEach(li => li.classList.remove('active'));

		this.parentElement.classList.add('active');
	});
});;

