const fragmentContainer = fragmentElement.querySelector('.global-modular-form');
const submitBtn =
    fragmentContainer.querySelector('.form-container [type="submit"].submit-btn') ||
    fragmentContainer.querySelector('.submit-btn');

const recaptchaWrap = fragmentContainer.querySelector('#recaptchaWrap');
const recaptchaEl = fragmentContainer.querySelector('#recaptchaEl');

let recaptchaReady = false;
let recaptchaFailed = false;

const SITE_KEY = (recaptchaEl?.getAttribute('data-sitekey') || '').trim();
const SHOULD_TRY_RECAPTCHA = SITE_KEY && SITE_KEY !== 'null' && SITE_KEY !== 'undefined';
const TIPOS_DENUNCIA = (configuration.tiposDenuncia || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
const UNIDADE_ENVOLVIDA = (configuration.unidadeEnvolvida || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);

function loadRecaptchaSafely({ timeoutMs = 2500 } = {}) {
    return new Promise((resolve) => {
        if (!SHOULD_TRY_RECAPTCHA) {
            recaptchaFailed = true;
            recaptchaReady = false;
            if (recaptchaWrap) recaptchaWrap.style.display = 'none';
            if (submitBtn) submitBtn.disabled = false;
            return resolve(false);
        }

        if (window.grecaptcha && typeof window.grecaptcha.render === 'function') {
            recaptchaReady = true;
            recaptchaFailed = false;
            if (recaptchaWrap) recaptchaWrap.style.display = 'block';
            if (submitBtn) submitBtn.disabled = false;
            return resolve(true);
        }

        let done = false;

        const finish = (ok) => {
            if (done) return;
            done = true;
            recaptchaReady = ok;
            recaptchaFailed = !ok;
            if (recaptchaWrap) recaptchaWrap.style.display = ok ? 'block' : 'none';
            if (!ok && submitBtn) submitBtn.disabled = false;
            resolve(ok);
        };

        const t = setTimeout(() => finish(false), timeoutMs);

        const s = document.createElement('script');
        s.src = 'https://www.google.com/recaptcha/api.js?render=explicit';
        s.async = true;
        s.defer = true;

        s.onload = () => {
            clearTimeout(t);
            try {
                if (window.grecaptcha && typeof window.grecaptcha.render === 'function') {
                    window.grecaptcha.ready(() => {
                        try {
                            window.grecaptcha.render(recaptchaEl, { sitekey: SITE_KEY });
                            finish(true);
                        } catch (e) {
                            finish(false);
                        }
                    });
                } else {
                    finish(false);
                }
            } catch (e) {
                finish(false);
            }
        };

        s.onerror = () => {
            clearTimeout(t);
            finish(false);
        };

        document.head.appendChild(s);
    });
}

function checkRecaptcha() {
    if (!recaptchaReady || !submitBtn) return;
    try {
        const recaptchaResponse = window.grecaptcha.getResponse();
        submitBtn.disabled = !(recaptchaResponse && recaptchaResponse.length > 0);
    } catch (e) {
        submitBtn.disabled = false;
    }
}

const CLIENT_REF = window.URL.createObjectURL(new Blob([])).substring(31);

function setupPesquisaForm() {
    const formElement = fragmentContainer.querySelector('#pesquisaForm');
    if (!formElement || formElement.dataset.pesquisaBound === 'true') return;

    formElement.dataset.pesquisaBound = 'true';

    const step1 = formElement.querySelector('.pesquisa-step-1');
    const step2 = formElement.querySelector('.pesquisa-step-2');
    const nextBtn = formElement.querySelector('.pesquisa-next-btn');
    const backBtn = formElement.querySelector('.pesquisa-back-btn');

    const pfRadio = formElement.querySelector('#pesquisaPessoaFisica');
    const pjRadio = formElement.querySelector('#pesquisaPessoaJuridica');

    const pfFields = formElement.querySelector('.pesquisa-fields-pf');
    const pjFields = formElement.querySelector('.pesquisa-fields-pj');

    const tipoPessoaHidden = formElement.querySelector('#tipoPessoa');

    function clearErrors(container) {
        if (!container) return;
        container.querySelectorAll('input, select, textarea').forEach((field) => {
            formValidator.removeErrorFromGroup(field);
        });
    }

    function clearValues(container) {
        if (!container) return;
        container.querySelectorAll('input, select, textarea').forEach((field) => {
            if (field.type === 'radio' || field.type === 'checkbox') {
                field.checked = false;
            } else {
                field.value = '';
            }
        });
    }

    function toggleRequired(container, enabled) {
        if (!container) return;

        container.querySelectorAll('[data-required="true"]').forEach((field) => {
            if (enabled) {
                field.setAttribute('required', 'required');
                field.disabled = false;
            } else {
                field.removeAttribute('required');
                field.disabled = true;
                formValidator.removeErrorFromGroup(field);
            }
        });
    }

    function showPF() {
        if (tipoPessoaHidden) tipoPessoaHidden.value = 'pf';

        if (pfFields) pfFields.style.display = 'flex';
        if (pjFields) pjFields.style.display = 'none';

        toggleRequired(pfFields, true);
        toggleRequired(pjFields, false);
        clearErrors(pjFields);
    }

    function showPJ() {
        if (tipoPessoaHidden) tipoPessoaHidden.value = 'pj';

        if (pfFields) pfFields.style.display = 'none';
        if (pjFields) pjFields.style.display = 'flex';

        toggleRequired(pfFields, false);
        toggleRequired(pjFields, true);
        clearErrors(pfFields);
    }

    toggleRequired(pfFields, false);
    toggleRequired(pjFields, false);

    if (pfRadio) {
        pfRadio.addEventListener('change', function () {
            if (this.checked) {
                showPF();
                formValidator.removeErrorFromGroup(this);
            }
        });
    }

    if (pjRadio) {
        pjRadio.addEventListener('change', function () {
            if (this.checked) {
                showPJ();
                formValidator.removeErrorFromGroup(this);
            }
        });
    }

    if (nextBtn) {
        nextBtn.addEventListener('click', function () {
            const radioGroup = formElement.querySelector('input[name="tipoPessoaEscolha"]');

            if (!pfRadio?.checked && !pjRadio?.checked) {
                return;
            }

            if (radioGroup) formValidator.removeErrorFromGroup(radioGroup);

            if (pfRadio?.checked) showPF();
            if (pjRadio?.checked) showPJ();

            if (step1) step1.style.display = 'none';
            if (step2) step2.style.display = 'flex';
        });
    }

    if (backBtn) {
        backBtn.addEventListener('click', function () {
            if (step2) step2.style.display = 'none';
            if (step1) step1.style.display = 'block';
        });
    }
}

function FormValidator() {
    this.formData = {};

    this.collectFormData = function (form) {
        const formElement = fragmentContainer.querySelector("#" + form);
        if (!formElement) return {};

        const formData = {};
        const fields = formElement.querySelectorAll('input, select, textarea');

        fields.forEach(field => {
            if (field.disabled) return;

            const key = field.name || field.id;
            if (!key) return;

            if (field.type === 'radio') {
                if (field.checked) {
                    formData[key] = (field.value || '').trim();
                }
                return;
            }

            if (field.type === 'checkbox') {
                if (field.checked) {
                    if (!formData[key]) {
                        formData[key] = [];
                    }
                    formData[key].push((field.value || '').trim());
                }
                return;
            }

            formData[key] = (field.value || '').trim();
        });

        Object.keys(formData).forEach((key) => {
            if (Array.isArray(formData[key])) {
                formData[key] = formData[key].join(', ');
            }
        });

        this.formData = formData;
        return formData;
    };

    this.validateEmail = function (email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(email);
    };

    this.validatePhone = function (phone) {
        const cleaned = phone.replace(/\D/g, '');
        return cleaned.length === 10 || cleaned.length === 11;
    };

    this.validateCNPJ = function (cnpj) {
        const clean = cnpj.toUpperCase().replace(/[^A-Z0-9]/g, '');

        if (clean.length !== 14) return false;


        if (/^(.)\1{13}$/.test(clean)) return false;

        const base = clean.slice(0, 12);
        const dvInformado = clean.slice(12, 14);


        if (!/^[0-9]{2}$/.test(dvInformado)) return false;

        const charValue = (c) => c.charCodeAt(0) - 48;

        const calcularDigito = (base, pesos) => {
            let soma = 0;
            for (let i = 0; i < base.length; i++) {
                soma += charValue(base[i]) * pesos[i];
            }
            const resto = soma % 11;
            return resto < 2 ? 0 : 11 - resto;
        };

        const pesos1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
        const dv1 = calcularDigito(base, pesos1);

        const pesos2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
        const dv2 = calcularDigito(base + String(dv1), pesos2);

        return `${dv1}${dv2}` === dvInformado;
    };

    this.validateCPF = function (cpf) {
        const cleaned = cpf.replace(/\D/g, '');
        return cleaned.length === 11;
    };

    this.validateName = function (name) {
        return name.trim().length >= 8;
    };

    this.addErrorToGroup = function (field) {
        const formGroup = field.closest('.form-container-group');
        if (!formGroup) return;

        formGroup.classList.add('field-error');

        const label = formGroup.querySelector('.label-text, label');
        if (
            label &&
            !label.textContent.includes('(Campo Obrigatório)') &&
            field.hasAttribute('required')
        ) {
            const isRadioEmpty =
                field.type === 'radio' &&
                !field.form.querySelector(`input[name="${field.name}"]:checked`);

            const isCheckboxEmpty =
                field.type === 'checkbox' &&
                !field.form.querySelector(`input[name="${field.name}"]:checked`);

            const isFieldEmpty =
                field.type !== 'radio' &&
                field.type !== 'checkbox' &&
                !(field.value || '').trim();

            if (isRadioEmpty || isCheckboxEmpty || isFieldEmpty) {
                label.textContent = label.textContent.trim() + ' (Campo Obrigatório)';
            }
        }
    };

    this.removeErrorFromGroup = function (field) {
        const formGroup = field.closest('.form-container-group');
        if (!formGroup) return;

        formGroup.classList.remove('field-error');

        const label = formGroup.querySelector('.label-text, label');
        if (label && label.textContent.includes('(Campo Obrigatório)')) {
            label.textContent = label.textContent.replace(/\s*\(Campo Obrigatório\)/, '');
        }
    };

    this.validateField = function (field) {
        if (!field || field.disabled) return true;
        if (field.type === 'hidden') return true;

        if (field.type === 'radio') {
            const checked = field.form.querySelector(`input[name="${field.name}"]:checked`);

            if (field.hasAttribute('required') && !checked) {
                this.addErrorToGroup(field);
                return false;
            }

            this.removeErrorFromGroup(field);
            return true;
        }

        if (field.type === 'checkbox') {
            const checked = field.form.querySelectorAll(`input[name="${field.name}"]:checked`);

            if (field.hasAttribute('required') && checked.length === 0) {
                this.addErrorToGroup(field);
                return false;
            }

            this.removeErrorFromGroup(field);
            return true;
        }

        if (field.hasAttribute('required') && !(field.value || '').trim()) {
            this.addErrorToGroup(field);
            return false;
        }

        if ((field.id === 'nome' || field.id === 'nomePf' || field.id === 'nomePj' || field.id === 'nomeFantasia' || field.id === 'empresa') && field.value.trim()) {
            if (!this.validateName(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        if ((field.id === 'telefone' || field.id === 'telefonePf' || field.id === 'telefonePj') && field.value.trim()) {
            if (!this.validatePhone(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        if (field.id === 'cnpj' && field.value.trim()) {
            if (!this.validateCNPJ(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        if (field.id === 'cpf' && field.value.trim()) {
            if (!this.validateCPF(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        if (field.type === 'email' && field.value.trim()) {
            if (!this.validateEmail(field.value)) {
                this.addErrorToGroup(field);
                return false;
            }
        }

        this.removeErrorFromGroup(field);
        return true;
    };

    this.applyPhoneMask = function (input) {
        let value = input.value.replace(/\D/g, '');
        if (value.length > 11) {
            value = value.slice(0, 11);
        }

        if (value.length <= 10) {
            value = value.replace(/(\d{2})(\d{4})(\d{4})/, '($1) $2-$3');
        } else {
            value = value.replace(/(\d{2})(\d{5})(\d{4})/, '($1) $2-$3');
        }

        input.value = value;
    };

    this.applyCNPJMask = function (input) {
        let clean = input.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 14);

        const base = clean.slice(0, 12);
        const dv = clean.slice(12, 14).replace(/[^0-9]/g, '');
        clean = base + dv;

        let formatted = '';
        for (let i = 0; i < clean.length; i++) {
            if (i === 2 || i === 5) formatted += '.';
            else if (i === 8) formatted += '/';
            else if (i === 12) formatted += '-';
            formatted += clean[i];
        }

        input.value = formatted;
    };

    this.applyCPFMask = function (input) {
        let value = input.value.replace(/\D/g, '');
        if (value.length > 11) {
            value = value.slice(0, 11);
        }

        value = value.replace(/(\d{3})(\d)/, '$1.$2');
        value = value.replace(/(\d{3})(\d)/, '$1.$2');
        value = value.replace(/(\d{3})(\d{1,2})$/, '$1-$2');

        input.value = value;
    };

    this.applyDateMask = function (input) {
        let value = input.value.replace(/\D/g, '');

        if (value.length > 8) {
            value = value.slice(0, 8);
        }

        value = value.replace(/(\d{2})(\d)/, '$1/$2');
        value = value.replace(/(\d{2})(\d)/, '$1/$2');

        input.value = value;
    };

    this.setupFieldEvents = function (field) {
        const validator = this;

        if (field.dataset.eventsBound === 'true') return;
        field.dataset.eventsBound = 'true';

        if (field.id === 'telefone' || field.id === 'telefonePf' || field.id === 'telefonePj') {
            field.addEventListener('input', function () {
                validator.applyPhoneMask(this);
                validator.validateField(this);
            });
        }

        if (field.id === 'cnpj') {
            field.addEventListener('input', function () {
                validator.applyCNPJMask(this);
                validator.validateField(this);
            });
        }

        if (field.id === 'cpf') {
            field.addEventListener('input', function () {
                validator.applyCPFMask(this);
                validator.validateField(this);
            });
        }

        if (field.id === 'dataOcorrencia') {
            field.addEventListener('input', function () {
                validator.applyDateMask(this);
                validator.validateField(this);
            });
        }

        if (field.id === 'nome' || field.id === 'nomePf' || field.id === 'nomePj' || field.id === 'nomeFantasia') {
            field.addEventListener('input', function () {
                this.value = this.value.replace(/\d+/g, '');
                validator.validateField(this);
            });
        }

        if (field.type === 'radio') {
            field.addEventListener('change', function () {
                const radios = this.form.querySelectorAll(`input[name="${this.name}"]`);
                radios.forEach(radio => validator.removeErrorFromGroup(radio));
                validator.validateField(this);
            });
            return;
        }

        if (field.id === 'arquivoDenuncia') {
            field.addEventListener('change', function () {
                const file = this.files?.[0];

                if (!file) return;

                const maxSize = 2 * 1024 * 1024;
                const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];

                if (!allowedTypes.includes(file.type)) {
                    alert('Formato inválido. Utilize JPG, JPEG, PNG ou PDF.');
                    this.value = '';
                    return;
                }

                if (file.size > maxSize) {
                    alert('O arquivo deve ter no máximo 2MB.');
                    this.value = '';
                    return;
                }

                const uploadBox = fragmentContainer.querySelector('#uploadBox');
                const preview = fragmentContainer.querySelector('#uploadPreview');
                const fileName = fragmentContainer.querySelector('#uploadFileName');
                const fileSize = fragmentContainer.querySelector('#uploadFileSize');
                const removeBtn = fragmentContainer.querySelector('#removeFileBtn');
                const fileExt = fragmentContainer.querySelector('#uploadFileExt');

                fileName.textContent = file.name;
                fileSize.textContent = `${(file.size / 1024).toFixed(0)} KB`;
                fileExt.textContent = file.name.split('.').pop().toUpperCase();

                uploadBox.style.display = 'none';
                preview.style.display = 'flex';

                removeBtn.onclick = () => {
                    this.value = '';
                    preview.style.display = 'none';
                    uploadBox.style.display = 'flex';
                };
            });
        }

        field.addEventListener('blur', function () {
            validator.validateField(this);
        });

        field.addEventListener('change', function () {
            validator.validateField(this);
        });

        field.addEventListener('input', function () {
            validator.validateField(this);
        });
    };

    this.validateForm = function (form) {
        const validator = this;
        const formElement = fragmentContainer.querySelector("#" + form);
        if (!formElement) return;

        if (formElement.dataset.submitBound === 'true') return;
        formElement.dataset.submitBound = 'true';

        formElement.setAttribute('novalidate', 'novalidate');

        const allFields = Array.from(formElement.querySelectorAll('input, select, textarea'));
        allFields.forEach(field => validator.setupFieldEvents(field));

        const localSubmitBtn =
            formElement.querySelector('[type="submit"].submit-btn') ||
            formElement.querySelector('.submit-btn');

        function getFieldsToValidate() {
            return Array.from(formElement.querySelectorAll('input, select, textarea')).filter(field => {
                if (!field) return false;
                if (field.type === 'hidden') return false;
                if (field.disabled) return false;
                return true;
            });
        }

        function showFirstError() {
            const firstError = formElement.querySelector('.field-error');

            if (firstError) {
                firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });

                const input = firstError.querySelector('input, select, textarea');
                if (input && typeof input.focus === 'function') {
                    input.focus();
                }
            }
        }

        function runValidationAndSend(e) {
            if (e) {
                e.preventDefault();
                e.stopPropagation();
                if (typeof e.stopImmediatePropagation === 'function') {
                    e.stopImmediatePropagation();
                }
            }

            let isValid = true;
            const fieldsToValidate = getFieldsToValidate();

            fieldsToValidate.forEach(field => {
                validator.removeErrorFromGroup(field);
            });

            const validatedRadioNames = new Set();
            const validatedCheckboxNames = new Set();

            fieldsToValidate.forEach(field => {

                if (field.type === 'radio') {
                    if (validatedRadioNames.has(field.name)) return;
                    validatedRadioNames.add(field.name);
                }

                if (field.type === 'checkbox') {
                    if (validatedCheckboxNames.has(field.name)) return;
                    validatedCheckboxNames.add(field.name);
                }

                const ok = validator.validateField(field);

                if (!ok) {
                    isValid = false;
                }
            });

            if (!isValid) {
                if (localSubmitBtn) {
                    localSubmitBtn.disabled = false;
                    localSubmitBtn.textContent = 'Enviar';
                }
                showFirstError();
                return false;
            }

            let recaptchaResponse = '';
            if (recaptchaReady) {
                try {
                    recaptchaResponse = window.grecaptcha.getResponse() || '';
                } catch (err) {
                    recaptchaResponse = '';
                }

                if (!recaptchaResponse) {
                    if (localSubmitBtn) {
                        localSubmitBtn.disabled = true;
                        localSubmitBtn.textContent = 'Enviar';
                    }
                    return false;
                }
            }

            if (localSubmitBtn) {
                localSubmitBtn.disabled = true;
                localSubmitBtn.textContent = 'Enviando...';
            }

            const formData = validator.collectFormData(form);
            formValidator.sendFormData(formElement, formData);

            return false;
        }

        formElement.addEventListener('submit', runValidationAndSend, true);

        if (localSubmitBtn) {
            if (localSubmitBtn.getAttribute('type') !== 'button') {
                localSubmitBtn.setAttribute('type', 'button');
            }

            localSubmitBtn.addEventListener('click', runValidationAndSend);
        }
    };

