            <p><strong>E-mail:</strong> ${escapeHtml(formData.email)}</p>
            <p><strong>Telefone:</strong> ${escapeHtml(formData.telefone) || "Não informado"}</p>
            <p><strong>CNPJ:</strong> ${escapeHtml(formData.cnpj)}</p>
            <p><strong>Nome fantasia:</strong> ${escapeHtml(formData.nomeFantasia)}</p>
            <p><strong>Mensagem:</strong><br>${mensagem}</p>
