                    </span>
                    <span class="description oxygen-p2-regular " tabindex="0">
                        Obrigada por seu envio, por favor aguarde nosso contato.
                    </span>
                </div>
            `;
            }

            if (successMessage) successMessage.style.display = 'flex';
            if (formTitle) formTitle.style.display = 'none';
            if (formElement) formElement.style.display = 'none';
            if (formElement) formElement.reset();
            const uploadBox = formElement.querySelector('#uploadBox');
            const preview = formElement.querySelector('#uploadPreview');
            const fileInput = formElement.querySelector('#arquivoDenuncia');
            const fileName = formElement.querySelector('#uploadFileName');
            const fileSize = formElement.querySelector('#uploadFileSize');
            const fileExt = formElement.querySelector('#uploadFileExt');

            if (fileInput) fileInput.value = '';

            if (preview) preview.style.display = 'none';
            if (uploadBox) uploadBox.style.display = 'flex';

            if (fileName) fileName.textContent = '';
            if (fileSize) fileSize.textContent = '';
            if (fileExt) fileExt.textContent = '';

            if (configuration.formModel == "pesquisaForm" && formElement) {
                const step1 = formElement.querySelector('.pesquisa-step-1');
                const step2 = formElement.querySelector('.pesquisa-step-2');
                const pfFields = formElement.querySelector('.pesquisa-fields-pf');
                const pjFields = formElement.querySelector('.pesquisa-fields-pj');
                const tipoPessoaHidden = formElement.querySelector('#tipoPessoa');

                if (step2) step2.style.display = 'none';
                if (step1) step1.style.display = 'block';

                if (pfFields) pfFields.style.display = 'none';
                if (pjFields) pjFields.style.display = 'none';

                if (tipoPessoaHidden) tipoPessoaHidden.value = '';

                pfFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });

                pjFields?.querySelectorAll('[data-required="true"]').forEach((field) => {
                    field.removeAttribute('required');
                    field.disabled = true;
                    formValidator.removeErrorFromGroup(field);
                });
            }

            if (recaptchaReady) {
                try {
                    window.grecaptcha.reset();
                    if (submitBtn) submitBtn.disabled = true;
                } catch (e) { }
            } else {
                if (submitBtn) submitBtn.disabled = false;
            }

            if (submitBtn) {
                submitBtn.textContent = 'Enviar';
            }

            setTimeout(() => {
                if (successMessage) successMessage.style.display = 'none';
                if (formTitle) formTitle.style.display = 'inline';
                if (formElement) formElement.style.display = 'flex';

                if (submitBtn) {
                    submitBtn.textContent = 'Enviar';
                    submitBtn.disabled = recaptchaReady ? true : false;
                }
            }, timeout);

            return true;
        }

        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Enviar';
        }

        return false;
    };
