(function () {
    function initfragmentReady() {
        const tipoDenunciaSelect = fragmentElement.querySelector('#tipoDenuncia');
        if (
            configuration.formModel === 'denunciaForm' &&
            tipoDenunciaSelect &&
            tipoDenunciaSelect.dataset.loaded !== 'true'
        ) {
            tipoDenunciaSelect.dataset.loaded = 'true';

            tipoDenunciaSelect.innerHTML = '<option value="">Selecione</option>';

            TIPOS_DENUNCIA.forEach(tipo => {
                const option = document.createElement('option');
                option.value = tipo;
                option.textContent = tipo;
                tipoDenunciaSelect.appendChild(option);
            });
        }
        const localUnidadeSelect = fragmentElement.querySelector('#localUnidade');
        if (
            configuration.formModel === 'denunciaForm' &&
            localUnidadeSelect &&
            localUnidadeSelect.dataset.loaded !== 'true'
        ) {
            localUnidadeSelect.dataset.loaded = 'true';

            localUnidadeSelect.innerHTML = '<option value="">Selecione</option>';

            UNIDADE_ENVOLVIDA.forEach(tipo => {
                const option = document.createElement('option');
                option.value = tipo;
                option.textContent = tipo;
                localUnidadeSelect.appendChild(option);
            });
        }

        const inputsQ = fragmentElement.querySelectorAll("#quntasVidas");
        inputsQ.forEach(function (input) {
            if (input.dataset.onlyNumbersBound === 'true') return;
            input.dataset.onlyNumbersBound = 'true';

            input.addEventListener("input", function () {
                this.value = this.value.replace(/[^0-9]/g, "");
            });
        });

        const inputsNome = fragmentElement.querySelectorAll("#nome, #nomePf, #nomePj");
        inputsNome.forEach(function (input) {
            if (input.dataset.onlyNameBound === 'true') return;
            input.dataset.onlyNameBound = 'true';

            input.addEventListener("input", function () {
                this.value = this.value.replace(/\d+/g, "");
            });

            input.addEventListener("paste", function () {
                setTimeout(() => {
                    this.value = this.value.replace(/\d+/g, "");
                }, 0);
            });
        });

        const ufField = fragmentElement.querySelector("#uf");
        const cidadeSelect = fragmentElement.querySelector("#cidade");

        if (ufField && cidadeSelect && ufField.dataset.cityLoaderBound !== 'true') {
            ufField.dataset.cityLoaderBound = 'true';

            ufField.addEventListener("change", function () {
                const uf = this.value;

                cidadeSelect.disabled = true;
                cidadeSelect.innerHTML = '<option value="">Carregando...</option>';

                if (!uf) {
                    cidadeSelect.innerHTML = '<option value="">Selecione</option>';
                    cidadeSelect.disabled = true;
                    return;
                }

                fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${uf}/municipios`)
                    .then(response => response.json())
                    .then(cidades => {
                        cidadeSelect.innerHTML = '<option value="">Selecione</option>';
                        cidadeSelect.disabled = false;

                        cidades.sort((a, b) => a.nome.localeCompare(b.nome));

                        cidades.forEach(cidade => {
                            const option = document.createElement("option");
                            option.value = cidade.nome;
                            option.textContent = cidade.nome;
                            cidadeSelect.appendChild(option);
                        });
                    })
                    .catch(() => {
                        cidadeSelect.innerHTML = '<option value="">Erro ao carregar</option>';
                        cidadeSelect.disabled = true;
                    });
            });
        }

        const root = fragmentElement || document;
        const els = root.querySelectorAll('[data-toggle="tooltip"]:not([data-tooltip-initialized="true"])');

        els.forEach((el) => {
            el.setAttribute('data-tooltip-initialized', 'true');

            if (window.bootstrap && bootstrap.Tooltip) {
                new bootstrap.Tooltip(el);
                return;
            }

            if (window.$ && $.fn && $.fn.tooltip) {
                $(el).tooltip();
            }
        });

        if (configuration.formModel == "pesquisaForm") {
            setupPesquisaForm();
        }
    }

    document.addEventListener('DOMContentLoaded', initfragmentReady);
    Pagina.on('endNavigate', initfragmentReady);
})();;

