const card = fragmentElement.querySelector('.material-card');
const link = fragmentElement.querySelector('.material-link');

if (card && link && !card.dataset.materialCardInitialized) {
	card.dataset.materialCardInitialized = 'true';

	const isEditMode = () => {
		return document.body.classList.contains('has-edit-mode-menu');
	};

	const hasValidLink = () => {
		const href = (link.getAttribute('href') || '').trim();

		return href && href !== '#';
	};

	/*
	 * Impede que o link padrão "#" mova a página para o topo
	 * enquanto nenhum arquivo ou URL estiver selecionado.
	 */
	link.addEventListener('click', (event) => {
		if (isEditMode()) {
			return;
		}

		if (!hasValidLink()) {
			event.preventDefault();
		}
	});

	/*
	 * Faz toda a área do card acionar o link editável.
	 */
	card.addEventListener('click', (event) => {
		if (isEditMode()) {
			return;
		}

		/*
		 * Quando o usuário clicar diretamente no link,
		 * deixa o navegador executar o comportamento normal.
		 */
		if (event.target.closest('.material-link')) {
			return;
		}

		/*
		 * Evita interferir caso algum elemento interativo
		 * seja inserido posteriormente no card.
		 */
		if (
			event.target.closest(
				'a, button, input, select, textarea, [role="button"]'
			)
		) {
			return;
		}

		if (!hasValidLink()) {
			return;
		}

		link.click();
	});
};

