(function () {
    const root = fragmentElement.querySelector('.bank-data-update-fragment');

    if (!root || root.dataset.initialized === 'true') {
        return;
    }

    root.dataset.initialized = 'true';

    const form = root.querySelector('#bankDataUpdateForm');
    const title = root.querySelector('.bank-data-title');
    const submitBtn = root.querySelector('.submit-btn');
    const formStatus = root.querySelector('#formStatus');
    const successMessage = root.querySelector('#successMessage');
    const emailToInput = root.querySelector('#emailTo');

    const fileInput = root.querySelector('#arquivoComprovante');
    const uploadGroup = root.querySelector('#uploadGroup');
    const uploadBox = root.querySelector('#uploadBox');
    const uploadPreview = root.querySelector('#uploadPreview');
    const uploadFileName = root.querySelector('#uploadFileName');
    const uploadFileSize = root.querySelector('#uploadFileSize');
    const uploadFileExt = root.querySelector('#uploadFileExt');
    const removeFileBtn = root.querySelector('#removeFileBtn');

    const recaptchaWrap = root.querySelector('#recaptchaWrap');
    const recaptchaEl = root.querySelector('#recaptchaEl');

    if (!form || !submitBtn) {
        return;
    }

    const MAX_FILE_SIZE = 2 * 1024 * 1024;
    const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];
    const ALLOWED_EXTENSIONS = ['jpg', 'jpeg', 'png', 'pdf'];
    const API_PATH = '/api/servicos/email/enviar';

    const fragmentConfiguration =
        typeof configuration !== 'undefined' && configuration
            ? configuration
            : {};

    const SITE_KEY = String(
        recaptchaEl?.dataset.sitekey ||
        fragmentConfiguration.recaptchaSiteKey ||
        ''
    ).trim();

    const SITE_KEY_SOURCE =
        recaptchaEl?.dataset.sitekeySource ||
        (fragmentConfiguration.recaptchaSiteKey ? 'fragmentConfiguration' : 'none');

    // O reCAPTCHA é exigido somente em produção.
    // A verificação usa apenas o hostname para não depender da URL ou da página atual.
    const CURRENT_HOSTNAME = window.location.hostname.toLowerCase();
    const NON_PRODUCTION_HOST_PATTERNS = [
        /(^|[.-])hml([.-]|$)/,
        /(^|[.-])stg([.-]|$)/,
        /(^|[.-])homolog([.-]|$)/,
        /(^|[.-])homologacao([.-]|$)/,
        /(^|[.-])staging([.-]|$)/,
        /^localhost$/,
        /^127\.0\.0\.1$/
    ];
    const SHOULD_USE_RECAPTCHA = !NON_PRODUCTION_HOST_PATTERNS.some((pattern) =>
        pattern.test(CURRENT_HOSTNAME)
    );

    let selectedFile = null;
    let recaptchaWidgetId = null;
    let recaptchaPassed = false;
    let recaptchaUnavailable = false;
    let sending = false;

    function onlyDigits(value) {
        return String(value || '').replace(/\D/g, '');
    }

    function escapeHtml(value) {
        return String(value ?? '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function formatPhone(value) {
        const digits = onlyDigits(value).slice(0, 11);

        if (digits.length <= 2) {
            return digits ? `(${digits}` : '';
        }

        if (digits.length <= 6) {
            return `(${digits.slice(0, 2)}) ${digits.slice(2)}`;
        }

        if (digits.length <= 10) {
            return `(${digits.slice(0, 2)}) ${digits.slice(2, 6)}-${digits.slice(6)}`;
        }

        return `(${digits.slice(0, 2)}) ${digits.slice(2, 7)}-${digits.slice(7)}`;
    }

    /**
     * Normaliza o CNPJ para o formato sem pontuação.
     *
     * Regra aplicada neste formulário:
     * - posições 1 a 8: letras de A a Z ou números;
     * - posições 9 a 14: somente números;
     * - posições 13 e 14: dígitos verificadores numéricos.
     */
    function normalizeCNPJ(value) {
        const rawValue = String(value || '')
            .toUpperCase()
            .replace(/[^A-Z0-9]/g, '');

        let normalized = '';

        for (const character of rawValue) {
            if (normalized.length >= 14) {
                break;
            }

            if (normalized.length < 8) {
                normalized += character;
                continue;
            }

            // Da 9ª posição em diante, desconsidera qualquer letra digitada ou colada.
            if (/\d/.test(character)) {
                normalized += character;
            }
        }

        return normalized;
    }

    function formatCNPJ(value) {
        const cnpj = normalizeCNPJ(value);
        let formatted = cnpj.slice(0, 2);

        if (cnpj.length > 2) {
            formatted += `.${cnpj.slice(2, 5)}`;
        }

        if (cnpj.length > 5) {
            formatted += `.${cnpj.slice(5, 8)}`;
        }

        if (cnpj.length > 8) {
            formatted += `/${cnpj.slice(8, 12)}`;
        }

        if (cnpj.length > 12) {
            formatted += `-${cnpj.slice(12, 14)}`;
        }

        return formatted;
    }

    function getCNPJCharacterValue(character) {
        // Regra oficial: valor ASCII do caractere menos 48.
        return character.charCodeAt(0) - 48;
    }

    function calculateCNPJDigit(characters, weights) {
        const sum = characters.split('').reduce((total, character, index) => {
            return total + (getCNPJCharacterValue(character) * weights[index]);
        }, 0);

        const remainder = sum % 11;
        return remainder === 0 || remainder === 1 ? 0 : 11 - remainder;
    }

    function isValidCNPJ(value) {
        const cnpj = normalizeCNPJ(value);

        // 8 posições alfanuméricas + 4 posições numéricas + 2 DVs numéricos.
        if (!/^[A-Z0-9]{8}\d{6}$/.test(cnpj)) {
            return false;
        }

        // Evita aceitar a sequência vazia clássica, cujo cálculo matemático resultaria em 00.
        if (/^0{14}$/.test(cnpj)) {
            return false;
        }

        const base = cnpj.slice(0, 12);
        const informedDigits = cnpj.slice(12);

        const firstDigit = calculateCNPJDigit(
            base,
            [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]
        );

        const secondDigit = calculateCNPJDigit(
            `${base}${firstDigit}`,
            [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]
        );

        return informedDigits === `${firstDigit}${secondDigit}`;
    }

    function isValidEmail(value) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
    }

    function isValidFullName(value) {
        return String(value || '').trim().length >= 8;
    }

    function isValidFile(file) {
        if (!file) {
            return { valid: false, message: 'Selecione o arquivo obrigatório.' };
        }

        const extension = (file.name.split('.').pop() || '').toLowerCase();
        const hasAllowedType = ALLOWED_MIME_TYPES.includes(file.type);
        const hasAllowedExtension = ALLOWED_EXTENSIONS.includes(extension);

        if (!hasAllowedType || !hasAllowedExtension) {
            return {
                valid: false,
                message: 'Formato inválido. Utilize JPG, JPEG, PNG ou PDF.'
            };
        }

        if (file.size > MAX_FILE_SIZE) {
            return {
                valid: false,
                message: 'O arquivo deve ter no máximo 2 MB.'
            };
        }

        return { valid: true, message: '' };
    }

    function getGroup(field) {
        return field?.closest('.form-group') || null;
    }

    function setFieldError(field, message) {
        const group = getGroup(field);

        if (!group) {
            return;
        }

        group.classList.add('field-error');
        field?.setAttribute('aria-invalid', 'true');

        const messageElement = group.querySelector('.field-message');
        if (messageElement) {
            messageElement.textContent = message;
        }
    }

    function clearFieldError(field) {
        const group = getGroup(field);

        if (!group) {
            return;
        }

        group.classList.remove('field-error');
        field?.removeAttribute('aria-invalid');

        const messageElement = group.querySelector('.field-message');
        if (messageElement) {
            messageElement.textContent = '';
        }
    }

    function setUploadError(message) {
        uploadGroup?.classList.add('field-error');
        uploadBox?.setAttribute('aria-invalid', 'true');

        const messageElement = uploadGroup?.querySelector('.field-message');
        if (messageElement) {
            messageElement.textContent = message;
        }
    }

    function clearUploadError() {
        uploadGroup?.classList.remove('field-error');
        uploadBox?.removeAttribute('aria-invalid');

        const messageElement = uploadGroup?.querySelector('.field-message');
        if (messageElement) {
            messageElement.textContent = '';
        }
    }

    function validateField(field) {
        if (!field || field.disabled) {
            return true;
        }

        const value = String(field.value || '').trim();
        const validationType = field.dataset.validate || '';

        if (field.required && !value) {
            setFieldError(field, 'Campo obrigatório.');
            return false;
        }

        if (!value) {
            clearFieldError(field);
            return true;
        }

        if (validationType === 'name' && !isValidFullName(value)) {
            setFieldError(field, 'Informe o nome completo do responsável.');
            return false;
        }

        if (validationType === 'phone') {
            const length = onlyDigits(value).length;
            if (length !== 10 && length !== 11) {
                setFieldError(field, 'Informe um telefone com DDD válido.');
                return false;
            }
        }

        if (validationType === 'cnpj' && !isValidCNPJ(value)) {
            setFieldError(field, 'Informe um CNPJ válido, com os dígitos verificadores corretos.');
            return false;
        }

        if (validationType === 'text' && value.length < 2) {
            setFieldError(field, 'Preencha este campo corretamente.');
            return false;
        }

        if (validationType === 'bank-code' && !/^\d{3}$/.test(value)) {
            setFieldError(field, 'Informe o código do banco com 3 dígitos.');
            return false;
        }

        if (validationType === 'agency' && !/^\d{1,6}$/.test(value)) {
            setFieldError(field, 'Informe uma agência válida, somente com números.');
            return false;
        }

        if (validationType === 'account' && !/^\d{1,12}-[\dX]$/i.test(value)) {
            setFieldError(field, 'Informe a conta com o dígito. Exemplo: 123456-7.');
            return false;
        }

        if (validationType === 'email' && !isValidEmail(value)) {
            setFieldError(field, 'Informe um e-mail válido.');
            return false;
        }

        clearFieldError(field);
        return true;
    }

    function validateUpload() {
        const validation = isValidFile(selectedFile);

        if (!validation.valid) {
            setUploadError(validation.message);
            return false;
        }

        clearUploadError();
        return true;
    }

    function validateForm() {
        const fields = Array.from(form.querySelectorAll('[data-validate]'));
        let isValid = true;

        fields.forEach((field) => {
            if (!validateField(field)) {
                isValid = false;
            }
        });

        if (!validateUpload()) {
            isValid = false;
        }

        return isValid;
    }

    function focusFirstError() {
        const firstError = form.querySelector('.form-group.field-error');

        if (!firstError) {
            return;
        }

        firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });

        const control = firstError.querySelector('input:not([type="file"]), #uploadBox');
        control?.focus();
    }

    function showFormStatus(message) {
        if (!formStatus) {
            return;
        }

        formStatus.textContent = message;
        formStatus.hidden = false;
        formStatus.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }

    function clearFormStatus() {
        if (!formStatus) {
            return;
        }

        formStatus.textContent = '';
        formStatus.hidden = true;
    }

    function updateSubmitState() {
        if (sending) {
            submitBtn.disabled = true;
            return;
        }

        // Em HML/STG o reCAPTCHA é ignorado. Em produção, o botão só
        // é liberado após a validação bem-sucedida do widget.
        if (!SHOULD_USE_RECAPTCHA) {
            submitBtn.disabled = false;
            return;
        }

        submitBtn.disabled = !recaptchaPassed;
    }

    function resetUpload() {
        selectedFile = null;

        if (fileInput) {
            fileInput.value = '';
        }

        if (uploadPreview) {
            uploadPreview.hidden = true;
        }

        if (uploadBox) {
            uploadBox.hidden = false;
        }

        if (uploadFileName) {
            uploadFileName.textContent = '';
        }

        if (uploadFileSize) {
            uploadFileSize.textContent = '';
        }

        if (uploadFileExt) {
            uploadFileExt.textContent = '';
        }
    }

    function showFilePreview(file) {
        if (uploadFileName) {
            uploadFileName.textContent = file.name;
        }

        if (uploadFileSize) {
            uploadFileSize.textContent = `${Math.ceil(file.size / 1024)} KB`;
        }

        if (uploadFileExt) {
            uploadFileExt.textContent = (file.name.split('.').pop() || 'ARQ').toUpperCase();
        }

        if (uploadBox) {
            uploadBox.hidden = true;
        }

        if (uploadPreview) {
            uploadPreview.hidden = false;
            uploadPreview.focus();
        }
    }

    function selectFile(file) {
        const validation = isValidFile(file);

        if (!validation.valid) {
            resetUpload();
            setUploadError(validation.message);
            return;
        }

        selectedFile = file;
        clearUploadError();
        showFilePreview(file);
    }

    function readFileAsBase64(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();

            reader.onload = function () {
                const result = String(reader.result || '');
                resolve(result.includes(',') ? result.split(',')[1] : result);
            };

            reader.onerror = function () {
                reject(new Error('Não foi possível ler o arquivo selecionado.'));
            };

            reader.readAsDataURL(file);
        });
    }

    function showRecaptchaError(message) {
        if (!recaptchaWrap) {
            return;
        }

        recaptchaWrap.hidden = false;

        let errorElement = recaptchaWrap.querySelector('.recaptcha-load-error');

        if (!errorElement) {
            errorElement = document.createElement('p');
            errorElement.className = 'recaptcha-load-error';
            errorElement.setAttribute('role', 'alert');
            errorElement.style.margin = '8px 0 0';
            errorElement.style.color = '#b42318';
            errorElement.style.fontSize = '14px';
            recaptchaWrap.appendChild(errorElement);
        }

        errorElement.textContent = message;
    }

    function clearRecaptchaError() {
        const errorElement = recaptchaWrap?.querySelector('.recaptcha-load-error');
        errorElement?.remove();
    }

    function loadRecaptchaApi(timeoutMs = 15000) {
        if (window.grecaptcha && typeof window.grecaptcha.render === 'function') {
            return Promise.resolve(window.grecaptcha);
        }

        if (window.__bankDataRecaptchaLoaderPromise) {
            return window.__bankDataRecaptchaLoaderPromise;
        }

        window.__bankDataRecaptchaLoaderPromise = new Promise((resolve, reject) => {
            let finished = false;
            let intervalId = null;
            let timeoutId = null;

            const finish = (error) => {
                if (finished) {
                    return;
                }

                finished = true;
                window.clearInterval(intervalId);
                window.clearTimeout(timeoutId);

                if (error) {
                    reject(error);
                    return;
                }

                resolve(window.grecaptcha);
            };

            const checkApi = () => {
                if (window.grecaptcha && typeof window.grecaptcha.render === 'function') {
                    finish();
                }
            };

            timeoutId = window.setTimeout(() => {
                finish(new Error('Tempo esgotado ao carregar a API do reCAPTCHA.'));
            }, timeoutMs);

            intervalId = window.setInterval(checkApi, 100);

            const existingScript = document.querySelector(
                'script[src*="google.com/recaptcha/api.js"], script[src*="recaptcha.net/recaptcha/api.js"]'
            );

            if (!existingScript) {
                const script = document.createElement('script');
                script.src = 'https://www.google.com/recaptcha/api.js?render=explicit';
                script.async = true;
                script.defer = true;
                script.onload = checkApi;
                script.onerror = () => finish(new Error('Falha de rede ao carregar a API do reCAPTCHA.'));
                document.head.appendChild(script);
            } else {
                existingScript.addEventListener('load', checkApi, { once: true });
                existingScript.addEventListener(
                    'error',
                    () => finish(new Error('Falha ao carregar o script já existente do reCAPTCHA.')),
                    { once: true }
                );
            }

            checkApi();
        }).catch((error) => {
            window.__bankDataRecaptchaLoaderPromise = null;
            throw error;
        });

        return window.__bankDataRecaptchaLoaderPromise;
    }

    async function setupRecaptcha() {
        console.info('[Dados bancários] Ambiente do reCAPTCHA:', {
            hostname: CURRENT_HOSTNAME,
            required: SHOULD_USE_RECAPTCHA,
            hasSiteKey: Boolean(SITE_KEY),
            siteKeySource: SITE_KEY_SOURCE
        });

        if (!SHOULD_USE_RECAPTCHA) {
            recaptchaUnavailable = true;
            recaptchaPassed = true;

            if (recaptchaWrap) {
                recaptchaWrap.hidden = true;
            }

            console.info(
                `[Dados bancários] reCAPTCHA desativado no ambiente não produtivo: ${CURRENT_HOSTNAME}`
            );
            updateSubmitState();
            return;
        }

        // Em produção, ausência de chave ou falha de carregamento NÃO libera o envio.
        recaptchaUnavailable = false;
        recaptchaPassed = false;

        if (recaptchaWrap) {
            recaptchaWrap.hidden = false;
        }

        if (!SITE_KEY || SITE_KEY === 'null' || SITE_KEY === 'undefined') {
            showRecaptchaError('Não foi possível carregar o reCAPTCHA: chave do site não configurada.');
            console.error('[Dados bancários] SITE_KEY não foi retornada pelo ContentHelper.');
            updateSubmitState();
            return;
        }

        try {
            clearRecaptchaError();
            const grecaptcha = await loadRecaptchaApi(15000);

            await new Promise((resolve) => {
                if (typeof grecaptcha.ready === 'function') {
                    grecaptcha.ready(resolve);
                } else {
                    resolve();
                }
            });

            // Evita erro de renderização duplicada após navegação SPA do Liferay.
            if (recaptchaEl && !recaptchaEl.querySelector('iframe')) {
                recaptchaEl.innerHTML = '';
            }

            if (recaptchaEl?.querySelector('iframe')) {
                recaptchaPassed = false;
                updateSubmitState();
                return;
            }

            recaptchaWidgetId = grecaptcha.render(recaptchaEl, {
                sitekey: SITE_KEY,
                callback: function () {
                    recaptchaPassed = true;
                    clearRecaptchaError();
                    clearFormStatus();
                    updateSubmitState();
                },
                'expired-callback': function () {
                    recaptchaPassed = false;
                    updateSubmitState();
                },
                'error-callback': function () {
                    recaptchaPassed = false;
                    showRecaptchaError('O reCAPTCHA apresentou um erro. Atualize a página e tente novamente.');
                    updateSubmitState();
                }
            });

            console.info('[Dados bancários] reCAPTCHA renderizado em produção.', {
                hostname: CURRENT_HOSTNAME,
                widgetId: recaptchaWidgetId
            });
        } catch (error) {
            console.error('[Dados bancários] Falha ao renderizar o reCAPTCHA em produção:', error);
            recaptchaPassed = false;
            showRecaptchaError(
                'Não foi possível carregar o reCAPTCHA. Verifique a chave, o domínio autorizado e o bloqueio de rede.'
            );
            updateSubmitState();
        }
    }

    function collectData() {
        return {
            nomeResponsavel: form.querySelector('#nomeResponsavel')?.value.trim() || '',
            telefoneContato: form.querySelector('#telefoneContato')?.value.trim() || '',
            cnpj: form.querySelector('#cnpj')?.value.trim() || '',
            razaoSocial: form.querySelector('#razaoSocial')?.value.trim() || '',
            codigoBanco: form.querySelector('#codigoBanco')?.value.trim() || '',
            nomeBanco: form.querySelector('#nomeBanco')?.value.trim() || '',
            agencia: form.querySelector('#agencia')?.value.trim() || '',
            contaCorrente: form.querySelector('#contaCorrente')?.value.trim() || '',
            emailAtualizado: form.querySelector('#emailAtualizado')?.value.trim() || ''
        };
    }

    function createEmailTemplate(data) {
        return `
            <body>
                <div>
                    <p><strong>Prezado(a): Responsável</strong></p>
                    <p>Segue solicitação de atualização de dados bancários enviada pelo formulário:</p>
                    <p><strong>Nome completo do responsável:</strong> ${escapeHtml(data.nomeResponsavel)}</p>
                    <p><strong>Telefone de contato:</strong> ${escapeHtml(data.telefoneContato)}</p>
                    <p><strong>CNPJ:</strong> ${escapeHtml(data.cnpj)}</p>
                    <p><strong>Razão Social:</strong> ${escapeHtml(data.razaoSocial)}</p>
                    <p><strong>Código do banco:</strong> ${escapeHtml(data.codigoBanco)}</p>
                    <p><strong>Nome do banco:</strong> ${escapeHtml(data.nomeBanco)}</p>
                    <p><strong>Agência:</strong> ${escapeHtml(data.agencia)}</p>
                    <p><strong>Conta corrente:</strong> ${escapeHtml(data.contaCorrente)}</p>
                    <p><strong>Email atualizado:</strong> ${escapeHtml(data.emailAtualizado)}</p>
                    <p><strong>URL da página:</strong> ${escapeHtml(window.location.href)}</p>
                </div>
            </body>
        `.replace(/\n/g, '').replace(/\s{2,}/g, ' ');
    }

    async function readApiResponse(response) {
        const responseText = await response.text();

        if (!responseText) {
            return {
                text: '',
                data: null
            };
        }

        try {
            return {
                text: responseText,
                data: JSON.parse(responseText)
            };
        } catch (error) {
            return {
                text: responseText,
                data: null
            };
        }
    }

    async function sendForm() {
        clearFormStatus();

        if (!validateForm()) {
            showFormStatus(
                'Revise os campos destacados e selecione o anexo obrigatório.'
            );

            focusFirstError();
            return;
        }

        if (SHOULD_USE_RECAPTCHA && !recaptchaPassed) {
            showFormStatus('Confirme o reCAPTCHA antes de enviar.');
            return;
        }

        const emailTo = String(
            fragmentConfiguration.emailTo ||
            emailToInput?.value ||
            ''
        ).trim();

        if (!emailTo) {
            showFormStatus(
                'O e-mail de destino não foi configurado no fragmento.'
            );

            console.error(
                '[Dados bancários] Configure o campo "E-mail de destino".'
            );

            return;
        }

        sending = true;
        submitBtn.textContent = 'Enviando...';
        updateSubmitState();

        try {
            const data = collectData();

            // O anexo é obrigatório no formulário, então sempre vai junto do e-mail.
            const base64 = await readFileAsBase64(selectedFile);

            const payload = {
                to: emailTo,
                subject: `Atualização de dados bancários - ${data.razaoSocial}`,
                body: createEmailTemplate(data),
                attachments: [{
                    fileName: selectedFile.name,
                    contentType: selectedFile.type || 'application/octet-stream',
                    content: base64
                }]
            };

            const apiURL = `${window.location.origin}${API_PATH}`;

            console.info('[Dados bancários] Requisição preparada:', {
                url: apiURL,
                to: payload.to,
                subject: payload.subject,
                bodyLength: payload.body.length,
                nomeArquivo: selectedFile.name,
                tipoArquivo: selectedFile.type,
                tamanhoArquivoBytes: selectedFile.size,
                tamanhoBase64: base64.length
            });

            const response = await fetch(apiURL, {
                method: 'POST',
                headers: {
                    Accept: 'application/json',
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            const apiResponse = await readApiResponse(response);

            console.info('[Dados bancários] Resposta da API:', {
                ok: response.ok,
                status: response.status,
                statusText: response.statusText,
                body: apiResponse.data || apiResponse.text
            });

            if (!response.ok) {
                const backendMessage =
                    apiResponse.data?.retorno?.detalhe ||
                    apiResponse.data?.retorno?.mensagem ||
                    apiResponse.data?.error ||
                    apiResponse.data?.message ||
                    apiResponse.text ||
                    `Falha no envio. Status HTTP ${response.status}.`;

                throw new Error(backendMessage);
            }

            form.reset();
            resetUpload();
            form.hidden = true;

            if (title) {
                title.hidden = true;
            }

            if (successMessage) {
                successMessage.hidden = false;
                successMessage.focus?.();
            }
        } catch (error) {
            console.error(
                '[Dados bancários] Erro no envio:',
                error
            );

            const errorMessage =
                error instanceof Error
                    ? error.message
                    : 'Erro desconhecido durante o envio.';

            showFormStatus(
                `Não foi possível enviar o formulário. ${errorMessage}`
            );

            if (
                recaptchaWidgetId !== null &&
                window.grecaptcha
            ) {
                try {
                    window.grecaptcha.reset(
                        recaptchaWidgetId
                    );

                    recaptchaPassed = false;
                } catch (recaptchaError) {
                    console.error(
                        '[Dados bancários] Erro ao reiniciar o reCAPTCHA:',
                        recaptchaError
                    );
                }
            }
        } finally {
            sending = false;
            submitBtn.textContent = 'Enviar';
            updateSubmitState();
        }
    }

    form.querySelectorAll('[data-validate]').forEach((field) => {
        field.addEventListener('blur', function () {
            validateField(this);
        });

        field.addEventListener('input', function () {
            if (this.id === 'telefoneContato') {
                this.value = formatPhone(this.value);
            }

            if (this.id === 'cnpj') {
                this.value = formatCNPJ(this.value);
            }

            if (this.id === 'codigoBanco' || this.id === 'agencia') {
                this.value = onlyDigits(this.value);
            }

            if (this.id === 'contaCorrente') {
                this.value = this.value
                    .toUpperCase()
                    .replace(/[^0-9X-]/g, '')
                    .replace(/-{2,}/g, '-')
                    .replace(/^-/g, '');
            }

            if (getGroup(this)?.classList.contains('field-error')) {
                validateField(this);
            }
        });
    });

    fileInput?.addEventListener('change', function () {
        selectFile(this.files?.[0] || null);
    });

    uploadBox?.addEventListener('keydown', function (event) {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            fileInput?.click();
        }
    });

    ['dragenter', 'dragover'].forEach((eventName) => {
        uploadBox?.addEventListener(eventName, function (event) {
            event.preventDefault();
            this.classList.add('is-dragging');
        });
    });

    ['dragleave', 'drop'].forEach((eventName) => {
        uploadBox?.addEventListener(eventName, function (event) {
            event.preventDefault();
            this.classList.remove('is-dragging');
        });
    });

    uploadBox?.addEventListener('drop', function (event) {
        const file = event.dataTransfer?.files?.[0] || null;
        selectFile(file);
    });

    removeFileBtn?.addEventListener('click', function () {
        resetUpload();
        setUploadError('Selecione o arquivo obrigatório.');
        uploadBox?.focus();
    });

    form.addEventListener('submit', function (event) {
        event.preventDefault();
        event.stopPropagation();

        if (!sending) {
            sendForm();
        }
    });

    if (!SHOULD_USE_RECAPTCHA && recaptchaWrap) {
        recaptchaWrap.hidden = true;
    }

    updateSubmitState();
    setupRecaptcha();
})();;

